// DIAGNOSTIC_CHECKS: 308 checks across 27 categories
export interface DiagnosticCheck {
  id: string;
  category: string;
  categoryNumber: number;
  title: string;
  description?: string;
  failCondition: string;
  mode: "FLAW" | "GAP";
  severity: "Critical" | "High" | "Medium" | "Low";
  requiresEvidence: boolean;
  siteType: "universal" | "saas" | "ecommerce" | "service" | "b2b" | "creator" | "local";
  pageType?: "any" | "homepage" | "pricing" | "product" | "about" | "landing";
  passLabel?: string;
}

const DIAGNOSTIC_CHECKS: DiagnosticCheck[] = [
  { id: 'HERO_001', category: 'Hero Section', categoryNumber: 1, title: 'Headline is benefit-absent', failCondition: 'FAIL if the HERO Headline names only what the product IS — a product, feature, category, or brand attribute — with no user outcome, transformation, or result (e.g. "AI-powered analytics platform", "Premium leather wallets"). PASS if it states a concrete outcome, change, or end-result the visitor gets (e.g. "Get paid 3 days faster", "Sleep through the night"). Judge the HERO Headline text only; quote it.', mode: 'FLAW', severity: 'Critical', requiresEvidence: true, siteType: 'universal', pageType: 'any', passLabel: 'Outcome-driven headline' },
  { id: 'HERO_002', category: 'Hero Section', categoryNumber: 1, title: 'Headline is too vague or generic', failCondition: 'FAIL if the HERO Headline is generic or abstract — it opens with filler ("Welcome to", "Discover", "The Best", "Premium Quality", "Your Journey") OR contains no concrete/specific term (no named noun, number, mechanism, or audience) so it could sit unchanged on a competitor\'s site. PASS if it carries at least one concrete, specific, or ownable term. Quote the HERO Headline.', mode: 'FLAW', severity: 'Critical', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'HERO_003', category: 'Hero Section', categoryNumber: 1, title: 'Headline does not name the customer or their problem', failCondition: 'FAIL if neither the HERO Headline nor Subheadline references who the product is for or the pain/desire it addresses — it reads brand-first, not customer-first. PASS if either names the audience (a role, segment, or situation) or the problem/outcome it solves. Quote the Headline/Subheadline.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'HERO_004', category: 'Hero Section', categoryNumber: 1, title: 'No subheadline or supporting copy in hero', failCondition: 'No subheadline or body copy exists within the hero section to expand on the headline claim or bridge to the CTA.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'HERO_005', category: 'Hero Section', categoryNumber: 1, title: 'Hero CTA absent above the fold', failCondition: 'No clickable CTA button exists within the first viewport. Visitor must scroll to find any action to take.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'universal', pageType: 'any', passLabel: 'CTA visible above fold' },
  { id: 'HERO_006', category: 'Hero Section', categoryNumber: 1, title: 'Hero CTA text is generic', failCondition: 'FAIL if the HERO CTA text is a bare generic verb with no benefit, specificity, or outcome — one of: Shop Now, Buy Now, Click Here, Submit, Go, Enter, Learn More, Get Started (or equivalent). PASS if the CTA names the outcome or offer (e.g. "Start my free trial", "Get my quote"). Quote the HERO CTA text.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'HERO_007', category: 'Hero Section', categoryNumber: 1, title: 'Hero image does not show product or outcome', failCondition: 'Hero image is abstract, decorative, or a lifestyle image with no clear product or transformation visible. Visitor cannot identify what is being sold from the image alone.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'HERO_008', category: 'Hero Section', categoryNumber: 1, title: 'No urgency or reason to act now in hero', failCondition: 'Hero section contains no time-sensitive element — no limited offer, no scarcity signal, no deadline, no "today only" framing.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'HERO_009', category: 'Hero Section', categoryNumber: 1, title: 'Hero does not address primary fear or objection', failCondition: 'No risk-reversal, guarantee, or objection-handling language visible in the hero such as "No contracts", "Money-back guarantee", or "No side effects".', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'HERO_010', category: 'Hero Section', categoryNumber: 1, title: 'Headline and hero image are misaligned', failCondition: 'The headline makes a claim the hero image does not visually support. Text and visual tell different stories.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'HERO_011', category: 'Hero Section', categoryNumber: 1, title: 'No social proof signal visible in hero', failCondition: 'No review count, star rating, customer count, or press mention is visible within or immediately below the hero section.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'HERO_012', category: 'Hero Section', categoryNumber: 1, title: 'Hero section is cluttered with competing focal points', failCondition: 'Hero contains more than one primary CTA, multiple competing headlines, or excessive visual elements that dilute attention from the main message.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'HERO_013', category: 'Hero Section', categoryNumber: 1, title: 'Headline is too long to parse at a glance', failCondition: 'FAIL if the HERO Headline is too long to grasp at a glance — more than ~12 words, or built from multiple clauses/sentences so its core meaning is not parseable in under ~8 words of meaning. PASS if the headline delivers its point in a single short, scannable line. A headline can be outcome-led and specific yet still FAIL here purely on length/complexity. Quote the headline and its word count.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any', passLabel: 'Headline scannable at a glance' },
  { id: 'TRUST_001', category: 'Trust & Credibility', categoryNumber: 2, title: 'No money-back guarantee mentioned', failCondition: 'No guarantee of any kind (satisfaction, money-back, results-based) is visible in the hero section, near the primary CTA, or adjacent to the pricing block. A guarantee buried in the footer or on a separate terms page does not function as a conversion signal — it must appear at the point where the visitor is deciding.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'universal', pageType: 'any', passLabel: 'Guarantee prominent near CTA' },
  { id: 'TRUST_002', category: 'Trust & Credibility', categoryNumber: 2, title: 'Guarantee exists but is buried', failCondition: 'A guarantee is mentioned but only in the footer, FAQ, or a separate page — not visible in the hero or near CTAs where purchase decisions happen.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'TRUST_004', category: 'Trust & Credibility', categoryNumber: 2, title: 'Testimonials are vague and unspecific', failCondition: 'FAIL if TESTIMONIALS are present but none cites a specific result, metric, or timeframe — only generic praise ("Great product!", "Highly recommend"). PASS if at least one testimonial names a concrete outcome. If no TESTIMONIALS block exists at all, PASS (absence is handled by SOCIAL_001, not here). Quote a vague testimonial.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'TRUST_005', category: 'Trust & Credibility', categoryNumber: 2, title: 'No photo or video testimonials', failCondition: 'All testimonials are text-only — no accompanying customer photo, video, or company logo anchor. Visual proof dramatically increases perceived credibility: a photo confirms the person exists; a company logo confirms professional context; a video confirms authentic speech. Text-only testimonials without any visual anchor are discounted as potentially fabricated, particularly for higher-price or skepticism-prone categories.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'TRUST_006', category: 'Trust & Credibility', categoryNumber: 2, title: 'No press or media mentions visible', failCondition: 'No press coverage, media mention, or publication logo is present — no "As Seen In" section, no named outlet quote, no recognizable publication mark. Third-party editorial coverage from a named outlet carries more credibility than any self-produced claim because it cannot be fabricated without falsification. A single specific press quote from a named outlet outperforms a generic testimonial from an unnamed source.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'TRUST_007', category: 'Trust & Credibility', categoryNumber: 2, title: 'No certifications or third-party validations', failCondition: 'No certifications, lab testing badges, industry awards, or third-party validation signals present for a product category where these are expected such as supplements, skincare, or food.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'TRUST_008', category: 'Trust & Credibility', categoryNumber: 2, title: 'No founder or brand story visible', failCondition: 'No founder identity, origin story, or human behind the product is visible. For expertise-dependent product categories — nutrition, finance, software, health, professional services — buyers assess whether the creator has relevant credentials or lived experience. A brand with no named founder or stated expertise has no answer to "why should I trust this person to solve my problem?" — an unanswered objection that suppresses conversion silently.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'TRUST_009', category: 'Trust & Credibility', categoryNumber: 2, title: 'Ingredient or material transparency absent', failCondition: 'For product categories where ingredient quality is a purchase factor such as supplements, skincare, food, or cleaning products, no ingredient sourcing, quality claim, or transparency signal is present.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'TRUST_010', category: 'Trust & Credibility', categoryNumber: 2, title: 'Trust badges absent near CTA', failCondition: 'No security badges, payment logos, SSL signals, or safety indicators visible near the primary CTA or purchase button.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'TRUST_011', category: 'Trust & Credibility', categoryNumber: 2, title: 'Review count is low or not displayed', failCondition: 'Review count shown is under 10, or the total review count is hidden and only a star rating is shown. Low visible review counts reduce rather than build trust.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'TRUST_012', category: 'Trust & Credibility', categoryNumber: 2, title: 'No before/after or transformation proof', failCondition: 'For transformation-based products such as skincare, supplements, fitness, or weight loss, no before/after imagery, results timeline, or measurable outcome proof exists.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'TRUST_013', category: 'Trust & Credibility', categoryNumber: 2, title: 'Claims made without evidence', failCondition: 'FAIL if the page makes a specific performance/efficacy claim — "clinically proven", "dermatologist approved", "increases energy by 40%", a named statistic — visible in HERO/BODY/SECTIONS, with no study, source, certification, or PERSUASION/PROOF authority signal backing it. PASS if such claims are backed, or no specific claims are made. Quote the unsupported claim.', mode: 'FLAW', severity: 'Critical', requiresEvidence: true, siteType: 'universal', pageType: 'any', passLabel: 'Claims backed by evidence' },
  { id: 'TRUST_014', category: 'Trust & Credibility', categoryNumber: 2, title: 'No customer count or social volume signal', failCondition: 'No "Join 10,000+ customers", "Trusted by X people", or equivalent social volume claim anywhere on the page.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  // REMOVED: TRUST_015 — duplicate of SPQ_001
  // REMOVED: TRUST_016 — duplicate of TRUST_001 + OBJ_002
  { id: 'TRUST_017', category: 'Trust & Credibility', categoryNumber: 2, title: 'No physical address or registered business signal', failCondition: 'No physical business address, registered company name, VAT or registration number, or business legitimacy signal is visible in the footer or contact section. Buyers who cannot confirm that a real business entity stands behind the product — particularly for international or high-ticket purchases — apply a legitimacy discount that suppresses conversion.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'CTA_001', category: 'CTA & Conversion', categoryNumber: 3, title: 'Only one CTA exists on the entire page', failCondition: 'The primary CTA appears only once. High-converting pages repeat the CTA at logical decision points — after proof, after features, after testimonials.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CTA_002', category: 'CTA & Conversion', categoryNumber: 3, title: 'CTA button text exceeds 5 words suggesting weak copy', failCondition: 'FAIL if any button in the CTAs block has text longer than 5 words. PASS if every CTA is 5 words or fewer. This is a literal word count over the CTAs block. Quote the over-length CTA and state its word count.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'CTA_003', category: 'CTA & Conversion', categoryNumber: 3, title: 'No CTA after testimonials section', failCondition: 'Testimonials section exists but is not followed by a CTA. This is a missed conversion moment — social proof is highest-intent real estate.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CTA_004', category: 'CTA & Conversion', categoryNumber: 3, title: 'No CTA after pricing section', failCondition: 'Pricing is displayed but no CTA immediately follows. Visitor sees price and has nowhere obvious to go next.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CTA_005', category: 'CTA & Conversion', categoryNumber: 3, title: 'Multiple CTAs on page use identical text creating confusion', failCondition: 'FAIL if two or more buttons in the CTAs block share exactly the same text while pointing to different destinations/contexts (visitors cannot distinguish the actions). PASS if CTA texts are distinct, or there is only one CTA. This is a literal duplicate check over the CTAs block. Quote the duplicated CTA text.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'CTA_006', category: 'CTA & Conversion', categoryNumber: 3, title: 'Urgency language absent from CTA', failCondition: 'CTA button or surrounding copy contains no urgency signal — no "Today Only", "Limited Stock", "Ends Sunday", or equivalent.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CTA_007', category: 'CTA & Conversion', categoryNumber: 3, title: 'No secondary CTA for non-ready visitors', failCondition: 'Page offers only a buy or purchase CTA with no lower-commitment option such as a quiz, free sample, email signup, or learn more for visitors not ready to purchase.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CTA_008', category: 'CTA & Conversion', categoryNumber: 3, title: 'Form fields create excessive friction', failCondition: 'Any visible lead capture or checkout form requests more than 3 fields before delivering value. Each additional field reduces completion rate.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CTA_009', category: 'CTA & Conversion', categoryNumber: 3, title: 'CTA does not match visitor awareness stage', failCondition: 'FAIL if the HERO CTA assumes purchase-ready intent ("Buy Now", "Subscribe") while the page gives no prior trust or understanding — a thin HERO with no proof/benefit before it and no lower-commitment alternative in the CTAs block. PASS if the CTA\'s commitment level matches the warm-up the page provides, or a low-commitment step is offered. Cite the HERO CTA and surrounding context.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CTA_010', category: 'CTA & Conversion', categoryNumber: 3, title: 'No free trial, sample, or risk-free entry point', failCondition: 'For products over $30, no low-risk entry point exists — no sample, trial size, starter kit, or free shipping on first order to reduce purchase barrier.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CTA_012', category: 'CTA & Conversion', categoryNumber: 3, title: 'Mobile CTA is too small or hard to tap', failCondition: 'Based on visual analysis, CTA button appears too small for comfortable mobile tapping or is positioned too close to other interactive elements.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CTA_013', category: 'CTA & Conversion', categoryNumber: 3, title: 'No urgency or action words in any CTA copy', failCondition: 'No CTA button on the page contains urgency or action-oriented language such as "Now", "Today", "Get", "Start", "Claim", "Join", or "Unlock". Passive CTA copy produces lower click-through rates than action-forward language.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CTA_014', category: 'CTA & Conversion', categoryNumber: 3, title: 'No visually distinct primary CTA class pattern detected', failCondition: 'No CTA button contains class names indicating a primary or prominent button designation such as btn-primary, cta-primary, button--primary, or equivalent. Without a coded primary CTA the page has no clear focal action hierarchy detectable in markup.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CTA_015', category: 'CTA & Conversion', categoryNumber: 3, title: 'No secondary conversion path — all CTAs lead to same destination', failCondition: 'All CTA links on the page point to the same destination URL. A page with only one CTA destination offers no alternative path for visitors not ready to convert through the primary flow. Secondary CTAs such as email capture, quiz entry, or content download retain visitors who would otherwise leave.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CTA_016', category: 'CTA & Conversion', categoryNumber: 3, title: 'No friction-reducing microcopy below or beside primary CTA', failCondition: 'No microcopy — "No credit card required", "Cancel anytime", "Free 14-day trial", or equivalent objection-neutralizing line — appears directly below or beside the primary CTA button. Microcopy at the CTA is the last line of objection handling before the visitor decides to act or abandon; its absence leaves purchase-blocking fears unaddressed at the highest-stakes moment.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any', passLabel: 'Friction-reducing microcopy present at CTA' },
  // REMOVED: CTA_017 — duplicate of HERO_006
  { id: 'MSG_001', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Value proposition not clear within 5 seconds', failCondition: 'FAIL if the HERO (Headline + Subheadline + CTA) does not let a first-time visitor answer all three of: what is it, who is it for, why does it matter — within ~5 seconds. PASS only if all three are answerable from the above-fold HERO text alone. Name which of the three is missing and quote the HERO text.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false, siteType: 'universal', pageType: 'any', passLabel: 'Value prop clear within 5 seconds' },
  { id: 'MSG_002', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Features listed without corresponding benefits', failCondition: 'FAIL if BODY TEXT / SECTIONS / H2 list features, specs, or ingredients without translating them into a customer outcome (e.g. "Contains Vitamin C" with no "brightens skin in 2 weeks"). PASS if features are paired with the benefit/outcome they produce. Quote a feature line that has no benefit attached.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'MSG_003', category: 'Messaging & Clarity', categoryNumber: 4, title: 'No differentiation from competitors stated', failCondition: 'No claim, comparison, or statement explains why this product is different or better than alternatives. Visitor has no reason to choose this over a competitor.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MSG_004', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Excessive jargon or technical language', failCondition: 'FAIL if the HERO Headline or BODY TEXT relies on industry jargon, acronyms, or technical terms with no plain-language explanation, for a general-consumer audience. PASS if the copy is plain-language or every technical term is explained in context. Quote the jargon term.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'MSG_005', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Copy is brand-centric rather than customer-centric', failCondition: 'Majority of copy uses "We", "Our", "Us" framing rather than "You" and "Your" framing. Brand talks about itself rather than the customer\'s situation.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MSG_006', category: 'Messaging & Clarity', categoryNumber: 4, title: 'No problem articulation before solution', failCondition: 'FAIL if the HERO and first SECTIONS/H2 jump straight to product/features with no acknowledgement of the visitor\'s pain point or desire first. PASS if a problem or desire is named before the solution. Cite the opening sequence (HERO → first H2/section).', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MSG_007', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Page is not skimmable', failCondition: 'FAIL if the page is a wall of prose — few or no H2/H3 subheadings relative to body length, and no section structure to break it up (see H2/H3 list, SECTIONS, PAGE STATS word count). PASS if subheadings/sections split the content into scannable blocks. Cite the H2/H3 count vs the word count.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MSG_008', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Pricing absent or hidden', failCondition: 'No pricing is visible on the homepage or landing page. Hiding price increases perceived risk and forces visitors to click through unnecessarily before knowing if the product fits their budget.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MSG_009', category: 'Messaging & Clarity', categoryNumber: 4, title: 'No objection handling copy present', failCondition: 'Page makes no attempt to address common purchase objections such as "Does it really work?", "Is it safe?", "What if it does not work for me?", or "How long until I see results?"', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MSG_010', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Headline uses jargon or insider language unknown to cold traffic', failCondition: 'FAIL if the HERO Headline (or primary value statement) contains jargon, proprietary terms, or insider shorthand a first-time visitor outside the core segment could not decode without prior context. PASS if the headline is comprehensible cold. Quote the headline term that requires insider knowledge.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'MSG_011', category: 'Messaging & Clarity', categoryNumber: 4, title: 'No audience specificity — page speaks to everyone and therefore no one', failCondition: 'FAIL if no named audience, segment, role, persona, or use-case appears anywhere in the HERO or BODY/SECTIONS — the copy addresses "everyone". PASS if a specific audience is named (e.g. "for Shopify stores", "for finance teams"). Quote the audience reference or confirm its absence.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MSG_012', category: 'Messaging & Clarity', categoryNumber: 4, title: 'Outcome language is abstract — no concrete or measurable result stated', failCondition: 'FAIL if every outcome stated in HERO/BODY is abstract ("grow your business", "save time", "work smarter") with no concrete or measurable result — no number, timeframe, or specific change. PASS if at least one outcome is concrete/measurable ("cut approval cycles from 5 days to 4 hours"). Quote the strongest outcome line.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  // REMOVED: MSG_013 — duplicate of NARR_001
  { id: 'MSG_014', category: 'Messaging & Clarity', categoryNumber: 4, title: 'No voice-of-customer language — copy sounds like marketing not a customer', failCondition: 'FAIL if HERO/BODY/TESTIMONIALS copy is marketing/brand voice with no plain customer phrasing — and COPY FRAMING shows brand-voice ("we/our") dominating with customer-voice ("you/your") low. PASS if the copy uses the words a customer would actually use, or testimonials carry that voice. Cite the COPY FRAMING counts or quote a brand-voice line.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MSG_015', category: 'Messaging & Clarity', categoryNumber: 4, title: 'No "how it works" explanation visible', failCondition: 'No explanation of how the product delivers its outcome is present — no mechanism, no process steps, no "here\'s what happens after you sign up." Buyers who cannot understand how a product works cannot believe it will work for them. A credible mechanism is the bridge between a benefit claim and purchase conviction.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SOCIAL_001', category: 'Social Proof', categoryNumber: 5, title: 'No reviews or testimonials anywhere on page', failCondition: 'Zero customer reviews, testimonials, or user-generated content detected anywhere on the homepage.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SOCIAL_002', category: 'Social Proof', categoryNumber: 5, title: 'Star rating shown without review count', failCondition: 'A star rating is displayed but the number of reviews is hidden or not shown. A star rating without a review count is unverifiable and carries little trust weight.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SOCIAL_003', category: 'Social Proof', categoryNumber: 5, title: 'No video testimonials', failCondition: 'All social proof is text-based. Video testimonials convert significantly higher than text — no video proof exists.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SOCIAL_005', category: 'Social Proof', categoryNumber: 5, title: 'No UGC or real customer imagery', failCondition: 'No user-generated content, customer photos, or real-world product usage imagery present. Stock photography used exclusively.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SOCIAL_006', category: 'Social Proof', categoryNumber: 5, title: 'No case studies or detailed success stories', failCondition: 'No long-form customer story, case study, or detailed transformation narrative exists anywhere on the site.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SOCIAL_007', category: 'Social Proof', categoryNumber: 5, title: 'Social proof not segmented by customer type', failCondition: 'FAIL if all TESTIMONIALS are one undifferentiated block with no segmentation by use-case, customer type, or role — different personas cannot find proof relevant to them. PASS if proof is grouped/labelled by persona or use-case, or there is too little proof to segment. Cite the testimonials.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SOCIAL_008', category: 'Social Proof', categoryNumber: 5, title: 'No third-party review platform integration', failCondition: 'No integration with third-party review platforms such as Trustpilot, Google Reviews, Yotpo, or Judge.me that provide independently verified social proof.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SOCIAL_009', category: 'Social Proof', categoryNumber: 5, title: 'No influencer or celebrity proof', failCondition: 'For lifestyle or consumer brands where influencer credibility is a category norm, no influencer mentions, partnerships, or celebrity endorsements are referenced.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SOCIAL_010', category: 'Social Proof', categoryNumber: 5, title: 'No community size or follower count signal', failCondition: 'No reference to community size, social following, or active customer community that signals brand legitimacy and scale.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },

  // ── Social Proof Quality (sub-group within Social Proof, category 5) ──────
  { id: 'SPQ_001', category: 'Social Proof', categoryNumber: 5, title: 'Testimonials lack specific outcomes or numbers', failCondition: 'FAIL if TESTIMONIALS present carry no quantified outcome or metric (no %, number, or measurable result) — only adjectival praise ("Amazing product"). PASS if at least one testimonial names a number/outcome ("Reduced onboarding time by 60%"). If no TESTIMONIALS block exists, PASS (covered by SOCIAL_001). Quote the testimonial.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any', passLabel: 'Specific outcome testimonials' },
  { id: 'SPQ_002', category: 'Social Proof', categoryNumber: 5, title: 'Testimonials anonymous — no name, role, or company visible', failCondition: 'Testimonials present include no full name, job title, or company attribution. Anonymous testimonials are perceived as fabricated and carry near-zero credibility versus attributed proof from a named individual at a known organization.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any', passLabel: 'Attributed testimonials' },
  { id: 'SPQ_003', category: 'Social Proof', categoryNumber: 5, title: 'Logo wall present but no context — logos float without outcome or use case', failCondition: 'FAIL if SOCIAL PROOF shows client logos but no accompanying quote, outcome, or use-case ties to them (logos float bare). PASS if logos are contextualized with a quote/result, or no logo wall exists. Cite the client-logos signal and whether any context accompanies it.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SPQ_004', category: 'Social Proof', categoryNumber: 5, title: 'Social proof not positioned before or adjacent to primary CTA', failCondition: 'Social proof elements — testimonials, reviews, or customer logos — do not appear before or adjacent to the primary CTA. Proof not in proximity to the conversion action cannot reduce the friction that exists at the moment of decision.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any', passLabel: 'Proof positioned near CTA' },
  { id: 'SPQ_005', category: 'Social Proof', categoryNumber: 5, title: 'Case studies present but measurable results absent', failCondition: 'Case studies or customer success stories exist but contain no measurable outcomes — no percentage improvements, revenue impact, time saved, or quantified business result. Case studies without numbers read as anecdote rather than evidence.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SPQ_006', category: 'Social Proof', categoryNumber: 5, title: 'No aggregate star rating or review count from a recognized review platform', failCondition: 'No star rating or review count from a recognized third-party platform such as G2, Trustpilot, Capterra, or Google Reviews is visible. Platform-attributed ratings carry significantly more credibility than on-site-only displays because they are independently verified.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SPQ_007', category: 'Social Proof', categoryNumber: 5, title: 'Social proof does not match apparent ideal customer profile', failCondition: 'FAIL if the TESTIMONIALS\' authors/roles/segments visibly do not match the page\'s stated audience — proof from a different buyer type than the copy targets. PASS if the proof reflects the named ICP, or audience/proof is unspecified (nothing to mismatch). Cite the testimonial author/role versus the named audience.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },

  { id: 'SEO_001', category: 'SEO & Metadata', categoryNumber: 6, title: 'Page title missing or generic', failCondition: 'Title tag is absent, matches the domain name only, or contains no target keyword or value proposition.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SEO_002', category: 'SEO & Metadata', categoryNumber: 6, title: 'Meta description missing or auto-generated', failCondition: 'Meta description is absent or is clearly auto-generated — truncated product description, repeating the title, or over 160 characters with no call to action.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SEO_003', category: 'SEO & Metadata', categoryNumber: 6, title: 'H1 absent or multiple H1s present', failCondition: 'Page has no H1 tag, or has more than one H1 tag. Both conditions damage SEO and indicate structural content problems.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SEO_004', category: 'SEO & Metadata', categoryNumber: 6, title: 'H1 contains no target keyword', failCondition: 'The H1 present does not contain a keyword a potential customer would use to find this type of product.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SEO_005', category: 'SEO & Metadata', categoryNumber: 6, title: 'Images have no alt text', failCondition: 'Product or hero images detected have empty or missing alt attributes. Both an SEO and accessibility failure.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SEO_006', category: 'SEO & Metadata', categoryNumber: 6, title: 'No structured data signals detected', failCondition: 'No schema markup signals detected for Product, Review, Organization, or BreadcrumbList. Structured data enables rich search results and increases click-through rate.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SEO_007', category: 'SEO & Metadata', categoryNumber: 6, title: 'Meta description has no call to action', failCondition: 'Meta description exists but reads as a passive description with no action verb or reason to click over competing results.', mode: 'FLAW', severity: 'Low', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SEO_008', category: 'SEO & Metadata', categoryNumber: 6, title: 'Page load speed signals suggest poor performance', failCondition: 'Visual analysis or page weight signals suggest the page has excessive image sizes, render-blocking elements, or other performance issues likely causing slow load times. Every 1 second delay reduces conversion 7%.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NAV_001', category: 'Navigation & UX', categoryNumber: 7, title: 'Navigation has too many items', failCondition: 'Primary navigation contains more than 7 items at the top level. Excessive navigation options split visitor attention and reduce click-through on priority pages.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NAV_002', category: 'Navigation & UX', categoryNumber: 7, title: 'No search functionality on multi-product site', failCondition: 'Site appears to have more than 10 products but no search bar is visible in the navigation. Visitors who cannot find products quickly leave.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NAV_003', category: 'Navigation & UX', categoryNumber: 7, title: 'Footer missing key pages', failCondition: 'Footer does not include links to Contact, About, Shipping Policy, Return Policy, and Privacy Policy. Missing footer links reduce trust and create legal exposure.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NAV_004', category: 'Navigation & UX', categoryNumber: 7, title: 'No breadcrumb navigation on product pages', failCondition: 'Product or category pages detected with no breadcrumb trail. Breadcrumbs improve navigation and SEO on multi-level sites.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'NAV_005', category: 'Navigation & UX', categoryNumber: 7, title: 'Mobile navigation not clearly accessible', failCondition: 'Based on visual analysis, mobile hamburger menu or navigation trigger is not clearly visible or accessible in the mobile viewport.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NAV_006', category: 'Navigation & UX', categoryNumber: 7, title: 'No clear path from homepage to purchase', failCondition: 'The conversion path from homepage to product to cart to checkout is not obvious. Visitor cannot intuitively navigate to purchase within 2 clicks from the homepage.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NAV_007', category: 'Navigation & UX', categoryNumber: 7, title: 'Collection pages lack filtering', failCondition: 'For sites with more than 15 products, no filtering or sorting options detected on collection pages. Visitors cannot narrow products to their specific need.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'NAV_008', category: 'Navigation & UX', categoryNumber: 7, title: 'No live chat or immediate support option', failCondition: 'No live chat widget, chatbot, or immediately visible support contact option present. For high-consideration purchases, real-time support significantly increases conversion.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NAV_009', category: 'Navigation & UX', categoryNumber: 7, title: 'Navigation contains more than 7 top-level items', failCondition: 'The primary navigation bar contains more than 7 top-level menu items. Navigation exceeding the 7-item cognitive limit forces visitors to scan and parse rather than quickly orient — choice overload at the navigation layer increases bounce rate before the visitor has engaged with any content.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NAV_010', category: 'Navigation & UX', categoryNumber: 7, title: 'No breadcrumb navigation on interior pages', failCondition: 'Interior pages — product, category, blog, or landing pages — display no breadcrumb navigation indicating the visitor\'s location within the site hierarchy. Visitors who cannot orient themselves within a multi-level site architecture abandon rather than backtrack through repeated browser back-button presses.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'NAV_011', category: 'Navigation & UX', categoryNumber: 7, title: 'Mobile navigation not accessible without scrolling', failCondition: 'On mobile viewports the primary navigation or hamburger menu is not visible without scrolling — it is positioned below the initial viewport. Mobile visitors who cannot access navigation within the first screen view have no path to discovery pages and abandon at above-average rates.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NAV_012', category: 'Navigation & UX', categoryNumber: 7, title: 'No clear back-to-home or logo-home link visible', failCondition: 'Page contains no logo link or explicit home link in a consistently expected position — top-left or top-center — that returns the visitor to the homepage. Visitors who lose their starting point have no recovery path and are more likely to close the tab than manually type the root URL.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'PSY_001', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'No loss aversion framing used', failCondition: 'FAIL if HERO/BODY frames the product only in terms of gains, with no cost-of-inaction, what-you-are-losing, or pain-of-staying framing. PASS if any loss-aversion line appears ("stop losing $X per month", "every day without X costs you Y"). Quote the loss line or confirm its absence.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'PSY_002', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'No authority markers present', failCondition: 'No expert endorsements, professional credentials, years in business, patents, research backing, or authority signals establish the brand as credible in its category.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'PSY_003', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'Scarcity signals absent', failCondition: 'No credible scarcity signal is present — no real inventory count, limited-batch quantity, or hard deadline creates purchase urgency. Fabricated countdown timers or "only 3 left" language that resets on refresh do not count; credible scarcity must be grounded in a real constraint such as production capacity, enrollment window, or stock level visible on the page.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'PSY_004', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'Scarcity or urgency signals appear fake', failCondition: 'FAIL only if scarcity/urgency copy IS present (see PERSUASION/PROOF scarcity-urgency, BODY) and it is generic or implausible — a countdown, "Only 3 left", or deadline with no real named constraint behind it. PASS if scarcity is grounded in a real constraint, OR if no scarcity/urgency is present at all (nothing fake to flag — do not FAIL absence here). Quote the urgency text.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'PSY_005', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'No reciprocity mechanism present', failCondition: 'No free value offered before the ask — no free guide, quiz, sample, educational content, or tool that gives before taking.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'PSY_006', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'Pain points not amplified before solution', failCondition: 'FAIL if the opening (HERO → first SECTIONS/H2) moves to the solution without dwelling on the visitor\'s painful current situation. PASS if the pain is established and felt before the solution is introduced. Cite the opening sequence.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'PSY_007', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'Aspiration framing absent', failCondition: 'FAIL if HERO/BODY focus only on features or problem-relief with no aspirational picture of the visitor\'s better future state or identity. PASS if an aspirational outcome/identity is painted. Quote the aspirational line or confirm its absence.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'PSY_008', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'No micro-commitment or consistency trigger', failCondition: 'No quiz, assessment, preference selector, or micro-commitment step gets visitors to invest small effort before the purchase ask, increasing follow-through likelihood.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'PSY_009', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'Social consensus language absent', failCondition: 'No consensus language normalizes the purchase decision — no customer count, bestseller designation, or "most popular" tier label is present. Effective consensus language uses specific numbers rather than round estimates: "over 14,300 businesses" reads as real and counted; "thousands of customers" reads as approximate and discounted. Round-number consensus claims are perceived as fabricated and provide weaker social proof than specific counts.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'PSY_010', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'Pricing not anchored against reference point', failCondition: 'FAIL if PRICING/BODY presents a price with no reference point — no crossed-out original, no higher tier or competitor comparison, no cost-of-the-problem anchor. PASS if a price anchor is present. SKIP only if no price is shown anywhere. Cite the price and any anchor.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'PSY_011', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'No authority signal from an expert, institution, or credential', failCondition: 'No authority signal — expert endorsement, institutional credential, professional certification, published research citation, or named advisor — is visible on the page. Authority signals transfer credibility to the product that the brand cannot manufacture for itself; without them the product relies entirely on self-produced claims that buyers discount.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  // REMOVED: PSY_012 — duplicate of PSY_008
  { id: 'PSY_013', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'No reciprocity trigger — no free value offered before asking for conversion', failCondition: 'Page asks for a purchase or signup without first providing any free value — no tool, guide, sample, trial, or useful content offered before the conversion ask. Reciprocity is one of the highest-leverage persuasion principles: buyers who have received something of value before being asked are measurably more likely to give something back.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'PSY_014', category: 'Psychology & Persuasion', categoryNumber: 8, title: 'Decoy pricing absent — no anchor tier to make target tier feel like a bargain', failCondition: 'FAIL if PRICING shows tiers but none functions as a premium anchor/decoy that makes the target tier feel like the obvious value by comparison. PASS if a higher anchor tier frames a target tier. SKIP if no pricing tiers are shown. Cite the tiers and which (if any) acts as the anchor.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'saas', pageType: 'pricing' },
  { id: 'PAGE_001', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No dedicated reviews or testimonials page', failCondition: 'Site has no standalone reviews, testimonials, or results page. Buyers actively research reviews before purchasing — a dedicated page captures this intent and provides SEO value.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'homepage' },
  { id: 'PAGE_002', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No "Why Us" or comparison page', failCondition: 'No page exists that directly compares this brand to competitors or answers why a visitor should choose this brand over alternatives. This is one of the highest-intent pages a buyer visits before converting.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'homepage' },
  { id: 'PAGE_003', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No FAQ page', failCondition: 'No FAQ page detected. FAQs handle objections at scale, reduce support load, and capture long-tail SEO traffic from pre-purchase questions.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'homepage' },
  { id: 'PAGE_004', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No how-it-works or ingredients page', failCondition: 'For products where mechanism matters such as supplements, skincare, tech, or services, no dedicated page explains how the product works or what is in it. Informed buyers convert better.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'homepage' },
  { id: 'PAGE_005', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No founder or brand story page', failCondition: 'No About page or founder story exists. Story-driven brands command higher loyalty and price premiums — the absence of a human story is a missed trust opportunity.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'homepage' },
  { id: 'PAGE_006', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No blog or educational content', failCondition: 'No blog, journal, or educational content hub exists. Educational content builds organic search traffic, establishes authority, and warms cold visitors before they reach product pages.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'homepage' },
  { id: 'PAGE_007', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No results or before/after gallery page', failCondition: 'For transformation products, no gallery, results page, or visual proof hub exists. A dedicated results page can be the single highest-converting page on a DTC site.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'homepage' },
  { id: 'PAGE_008', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No quiz or product finder tool', failCondition: 'For brands with multiple products or SKUs, no quiz or recommendation tool exists to guide visitors to the right product. Quizzes also capture email and segment leads.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'homepage' },
  { id: 'PAGE_009', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No bundle or multi-product page', failCondition: 'No bundle, kit, or multi-product offering detected. Bundles increase average order value and simplify the decision for visitors who want a complete solution.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'homepage' },
  { id: 'PAGE_010', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No loyalty or rewards program page', failCondition: 'No loyalty program, rewards scheme, or referral program exists or is referenced. Retention programs dramatically reduce customer acquisition costs over time.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'homepage' },
  { id: 'PAGE_011', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No community or user group page', failCondition: 'No community hub, Facebook group link, forum, or customer community exists. Community increases retention, generates UGC, and reduces churn.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'homepage' },
  { id: 'PAGE_012', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No press or media page', failCondition: 'No dedicated press page or media kit exists. For brands seeking PR and partnerships, a press page signals professionalism and is essential for media outreach.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'homepage' },
  { id: 'PAGE_013', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No dedicated pricing page or pricing section', failCondition: 'No dedicated pricing page exists and no pricing section appears on the homepage. SaaS buyers treat pricing as a mandatory pre-purchase research step — forcing them to contact sales to learn price signals a lack of transparency and dramatically reduces self-serve conversion.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'PAGE_014', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No product changelog or release history visible', failCondition: 'No changelog, release notes, or "what\'s new" page exists. Active product development is a primary confidence signal for SaaS buyers evaluating long-term vendor commitment — its absence signals stagnation and raises the risk of buying into abandoned software.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'PAGE_015', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No security or data handling page', failCondition: 'No dedicated security page, data handling statement, or privacy architecture overview exists. For SaaS products handling business data, the absence of a security page is an immediate disqualifier for enterprise and mid-market buyers whose procurement process requires documented security controls.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'PAGE_016', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No customer success stories or case study library', failCondition: 'No case study, customer story, or results showcase page exists. For SaaS products with longer sales cycles, case studies are the primary proof format used in buying committee decisions — their absence forces every prospect to rely on generic claims rather than peer-verified outcomes.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  // REMOVED: PAGE_017 — duplicate of SAAS_005
  { id: 'PAGE_018', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No ROI calculator or savings estimator available', failCondition: 'No ROI calculator, savings estimator, or outcome projection tool is present. For products whose value is quantifiable — time saved, cost reduced, revenue increased — an interactive calculator gives buyers a personalized number to anchor their purchase decision. A personalized ROI figure converts better than a generic claim because it translates abstract value into the buyer\'s specific context.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'PAGE_019', category: 'Page & Content Gaps', categoryNumber: 9, title: 'No dedicated objection-handling or FAQ section on pricing page', failCondition: 'Pricing page has no FAQ or objection-handling section below or adjacent to the pricing tiers. Pricing pages carry the highest buyer skepticism of any page type — objections about contract terms, upgrade paths, refund policy, and seat limits that are unanswered on the pricing page force a support conversation that adds friction and drops conversion.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'OFFER_001', category: 'Offer & Pricing', categoryNumber: 10, title: 'Pricing not clearly displayed', failCondition: 'Product pricing is absent from the homepage or requires multiple clicks to find. Hidden pricing increases bounce rate on price-sensitive purchases.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'OFFER_002', category: 'Offer & Pricing', categoryNumber: 10, title: 'No subscription or recurring purchase option', failCondition: 'For consumable products such as supplements, skincare, coffee, or cleaning products, no subscription or auto-ship option exists. Subscriptions dramatically increase lifetime value.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'OFFER_003', category: 'Offer & Pricing', categoryNumber: 10, title: 'No bundle discount or volume pricing', failCondition: 'No multi-unit discount, buy-more-save-more pricing, or bundle offer exists. Bundle pricing increases AOV and reduces per-unit cost perception.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'OFFER_004', category: 'Offer & Pricing', categoryNumber: 10, title: 'Free shipping threshold not visible', failCondition: 'Shipping cost or free shipping threshold is not visible until checkout. Unexpected shipping costs are the number one cause of cart abandonment.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'OFFER_005', category: 'Offer & Pricing', categoryNumber: 10, title: 'No payment plan or BNPL option', failCondition: 'For products over $50, no buy-now-pay-later option such as Afterpay, Klarna, or Shop Pay Installments exists. BNPL can increase conversion 20-30% on higher-ticket items.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'OFFER_006', category: 'Offer & Pricing', categoryNumber: 10, title: 'Offer value not framed against problem cost', failCondition: 'Price presented with no comparison to the cost of the alternative such as competitor price, cost of inaction, or professional service cost. Price feels higher when not anchored.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'OFFER_007', category: 'Offer & Pricing', categoryNumber: 10, title: 'No introductory or first-order incentive', failCondition: 'No first-order discount, welcome offer, free gift with purchase, or new customer incentive exists to reduce the friction of the first purchase.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'OFFER_008', category: 'Offer & Pricing', categoryNumber: 10, title: 'Sale or discount not clearly communicated', failCondition: 'A sale or promotional pricing exists but the original price, savings amount, or discount percentage is not clearly displayed alongside the sale price.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'EMAIL_001', category: 'Email & Retention', categoryNumber: 11, title: 'No email capture mechanism on homepage', failCondition: 'No email signup form, popup, flyout, or lead capture of any kind detected. Email list is the highest-ROI owned channel — its absence means all traffic is lost if visitors do not purchase immediately.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'EMAIL_002', category: 'Email & Retention', categoryNumber: 11, title: 'Email capture has no incentive', failCondition: 'An email signup exists but offers no reason to subscribe — no discount, free guide, early access, or value exchange. Unincentivized email capture converts at a fraction of incentivized capture.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'EMAIL_004', category: 'Email & Retention', categoryNumber: 11, title: 'No SMS capture option', failCondition: 'No SMS or text marketing signup exists. SMS has 98% open rates versus 20% for email — for e-commerce brands, SMS capture is a significant revenue lever.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'EMAIL_005', category: 'Email & Retention', categoryNumber: 11, title: 'No loyalty or referral program mentioned', failCondition: 'No referral program, loyalty points, or reward for repeat purchases is mentioned anywhere on the site. Referral programs can reduce CAC by 30-50%.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'EMAIL_006', category: 'Email & Retention', categoryNumber: 11, title: 'No post-purchase upsell or cross-sell path', failCondition: 'No signals of a post-purchase flow — no frequently bought together, no order bump, no thank-you page offer. Post-purchase is the highest-conversion moment and it is unused.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'EMAIL_007', category: 'Email & Retention', categoryNumber: 11, title: 'No content upgrade or lead magnet offered', failCondition: 'Email capture form relies on a generic newsletter signup with no specific content offer — no checklist, guide, template, or resource that gives a reason to subscribe beyond a vague "stay updated". Incentivized email capture with a specific lead magnet converts significantly higher than unincentivized forms.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'EMAIL_008', category: 'Email & Retention', categoryNumber: 11, title: 'No preference center or topic selection at email signup', failCondition: 'Email capture form offers no topic selection, interest categories, or preference indication. All subscribers receive identical content regardless of their stated interest, reducing relevance and increasing unsubscribe rates from mismatched messaging.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'EMAIL_009', category: 'Email & Retention', categoryNumber: 11, title: 'No social proof adjacent to email capture form', failCondition: 'Email capture form has no subscriber count, testimonial about the newsletter, or social proof signal adjacent to it. The absence of proof that others find value in subscribing removes a key motivator at the point of signup decision.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'EMAIL_010', category: 'Email & Retention', categoryNumber: 11, title: 'No send frequency expectation set at email capture', failCondition: 'Email signup form gives no indication of how often the subscriber will be contacted — no "weekly digest", "monthly updates", or equivalent frequency signal. Visitors who do not know how often they will be emailed default to assuming high frequency, increasing hesitation to subscribe.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'EMAIL_011', category: 'Email & Retention', categoryNumber: 11, title: 'Email capture form has no privacy reassurance', failCondition: 'Email capture form contains no privacy statement, "no spam" assurance, or data use explanation adjacent to the signup field. Privacy concern is the primary objection at the email capture step — visitors who cannot confirm their email will not be sold or spammed withhold the address, even when the lead magnet or offer is compelling.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'EMAIL_012', category: 'Email & Retention', categoryNumber: 11, title: 'Lead magnet or incentive not specific enough to motivate signup', failCondition: 'Email capture offer exists but is described in vague terms — "Get our newsletter", "Subscribe for updates", or "Join our list" — with no specific outcome, deliverable, or piece of value stated. A vague incentive does not overcome the privacy friction of submitting an email address; a specific, titled, and immediately useful lead magnet outperforms generic signup offers by a wide margin.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'PROD_001', category: 'Product Page', categoryNumber: 12, title: 'Product description leads with features not benefits', failCondition: 'Product page description opens with a list of features, ingredients, or specifications before establishing what the product does for the customer.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'product' },
  { id: 'PROD_002', category: 'Product Page', categoryNumber: 12, title: 'No usage instructions or how-to information', failCondition: 'Product page has no usage instructions, application guide, or how-to section. Uncertainty about how to use a product is a significant purchase barrier.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'product' },
  { id: 'PROD_003', category: 'Product Page', categoryNumber: 12, title: 'No results timeline or expectation setting', failCondition: 'For products where results take time such as supplements, skincare, or fitness, no timeline is given for when results can be expected. Uncertainty about outcomes reduces purchase confidence.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'product' },
  { id: 'PROD_004', category: 'Product Page', categoryNumber: 12, title: 'No comparison table against alternatives', failCondition: 'No comparison table contrasting this product against competitors or the brand\'s own product range exists on the product page.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'product' },
  { id: 'PROD_005', category: 'Product Page', categoryNumber: 12, title: 'No complementary product recommendations', failCondition: 'No "pairs well with", "complete the routine", or "frequently bought together" section exists on the product page. Cross-sell recommendations increase AOV significantly.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'product' },
  { id: 'PROD_006', category: 'Product Page', categoryNumber: 12, title: 'Reviews not integrated on product page', failCondition: 'Product page has no reviews section or review integration. 93% of consumers say reviews impact purchase decisions — their absence at the point of purchase is critical.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'ecommerce', pageType: 'product' },
  { id: 'PROD_007', category: 'Product Page', categoryNumber: 12, title: 'No product FAQ on product page', failCondition: 'No FAQ section on the product page to handle common objections at the moment of highest purchase intent.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'product' },
  { id: 'PROD_008', category: 'Product Page', categoryNumber: 12, title: 'Insufficient product imagery', failCondition: 'Product page has fewer than 3 product images, no lifestyle imagery, no ingredient or detail shots, or no video view. Insufficient imagery is a top reason for purchase abandonment on product pages.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'product' },
  { id: 'MOBILE_001', category: 'Mobile Experience', categoryNumber: 13, title: 'No viewport meta tag present', failCondition: 'Page HTML contains no <meta name="viewport"> tag. Without a viewport meta tag the browser renders the page at desktop width on mobile devices, forcing users to zoom and scroll horizontally — a fundamental mobile rendering failure.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MOBILE_002', category: 'Mobile Experience', categoryNumber: 13, title: 'No tel: click-to-call link for phone number', failCondition: 'A phone number is displayed on the page but is not wrapped in an href="tel:" link. Mobile visitors cannot tap to call — a significant friction point for service businesses and local commerce where phone conversion is a primary goal.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MOBILE_003', category: 'Mobile Experience', categoryNumber: 13, title: 'No mobile navigation pattern detected in HTML', failCondition: 'Page HTML contains no class patterns associated with mobile navigation such as hamburger, mobile-menu, nav-toggle, or menu-icon. Without a mobile navigation trigger visitors on small screens cannot access site navigation.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MOBILE_004', category: 'Mobile Experience', categoryNumber: 13, title: 'Images missing width and height attributes causing layout shift', failCondition: 'One or more img elements lack explicit width and height attributes. Without these the browser cannot reserve space before images load, causing layout shift that disrupts reading and harms Core Web Vitals CLS score.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MOBILE_005', category: 'Mobile Experience', categoryNumber: 13, title: 'No responsive image srcset attributes present', failCondition: 'No img elements use srcset or sizes attributes. Without responsive images the browser serves the same large desktop image to mobile devices, increasing data usage and load time unnecessarily on mobile connections.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MOBILE_006', category: 'Mobile Experience', categoryNumber: 13, title: 'Script tags missing defer or async causing render blocking', failCondition: 'One or more external script tags in the page lack both defer and async attributes. Synchronous scripts in the document head block HTML parsing and delay first contentful paint, directly harming perceived load speed on mobile connections.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MOBILE_007', category: 'Mobile Experience', categoryNumber: 13, title: 'No preload or prefetch hints in document head', failCondition: 'Page head contains no <link rel="preload">, <link rel="prefetch">, or <link rel="preconnect"> resource hints. These hints let the browser prioritize critical resources early and are especially impactful on mobile network speeds.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MOBILE_008', category: 'Mobile Experience', categoryNumber: 13, title: 'No touch gesture alternative for hover-dependent interactions', failCondition: 'Page contains elements that reveal content or trigger actions on CSS :hover — dropdown menus, tooltip triggers, or reveal effects — with no equivalent touch-accessible pattern such as a tap target, expandable element, or visible-by-default fallback. Hover states are inaccessible on touch devices, hiding content from mobile users.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MOBILE_009', category: 'Mobile Experience', categoryNumber: 13, title: 'Input fields missing appropriate type attributes', failCondition: 'One or more input elements use type="text" for fields where a more specific type is appropriate — email fields lack type="email", phone fields lack type="tel", numeric fields lack type="number". Without correct input types, mobile keyboards do not switch to the optimized layout, increasing entry errors and friction on touch devices.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MOBILE_010', category: 'Mobile Experience', categoryNumber: 13, title: 'Fixed position elements may obscure primary CTA on small viewports', failCondition: 'Page contains one or more elements with position:fixed or position:sticky detectable in inline styles or style attributes that could overlay the primary CTA or key content on viewports below 375px width. Persistent headers, banners, or chat widgets that cover conversion elements directly reduce conversion rate on small mobile screens.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MOBILE_011', category: 'Mobile Experience', categoryNumber: 13, title: 'No autocomplete attributes on name, email, or address fields', failCondition: 'Form fields for name, email, phone, or address do not include autocomplete attributes such as autocomplete="email", autocomplete="name", or autocomplete="tel". Without autocomplete hints, mobile users must manually type information their device could fill automatically, adding friction to every form interaction.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'MOBILE_012', category: 'Mobile Experience', categoryNumber: 13, title: 'Font size below 16px detected on body copy elements', failCondition: 'One or more body copy elements have a font-size value below 16px detectable in inline styles or style attributes. iOS Safari automatically zooms in on inputs and elements with font sizes below 16px, breaking the page layout during form interaction and disrupting the user experience on iPhone and iPad.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CHECK_001', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No payment provider logos or trust marks in HTML', failCondition: 'Page HTML contains no mention of recognized payment providers such as Visa, Mastercard, PayPal, Stripe, Apple Pay, or Google Pay. The absence of payment trust marks increases perceived financial risk for first-time buyers evaluating whether to share payment details.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'CHECK_002', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No free shipping mention anywhere on page', failCondition: 'Page contains no reference to free shipping, free delivery, or a shipping threshold. Unexpected shipping costs are the leading cause of cart abandonment — communicating free shipping or the threshold to qualify visibly on the landing page reduces this friction before it reaches checkout.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'CHECK_003', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No return or refund policy language visible on page', failCondition: 'Page contains no visible text related to returns, refunds, exchanges, or a satisfaction guarantee. Buyers evaluate return policies before purchasing — when this information is absent they must leave the page to find it, introducing dropout risk.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'CHECK_004', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No security or SSL reassurance language near purchase elements', failCondition: 'Page contains no text signals of purchase security such as "secure checkout", "encrypted", "SSL", "safe checkout", or "100% secure payment". Security reassurance copy adjacent to purchase triggers is a proven conversion lift, particularly for unfamiliar brands.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'CHECK_005', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No price transparency — no currency symbol visible on landing page', failCondition: 'Page contains no currency symbol such as $, £, €, or ¥. Visitors have no indication of pricing level or whether the product fits their budget without clicking through. Price transparency on landing pages reduces misaligned traffic and improves qualified click-through rate.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'CHECK_006', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No guest checkout or no-account-required language visible', failCondition: 'Page contains no text indicating that guest checkout is available or that account creation is not required to purchase. Forced account creation is the most commonly cited reason for checkout abandonment — communicating guest access on the landing page removes a pre-checkout objection before it surfaces.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'CHECK_007', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No express checkout option signal detected', failCondition: 'Page HTML contains no reference to Apple Pay, Google Pay, Shop Pay, PayPal One Touch, or equivalent single-tap express checkout providers. Express checkout options eliminate the manual card entry step and convert significantly higher for mobile purchasers who have payment methods stored on device.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'CHECK_008', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No order summary visible near payment step', failCondition: 'No persistent order summary, cart preview, or item confirmation is visible adjacent to or near the payment action. Visitors who cannot confirm what they are buying without navigating back experience doubt at the final conversion moment, increasing abandonment.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'CHECK_009', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No progress indicator on multi-step checkout', failCondition: 'A multi-step checkout flow exists but contains no step indicator, progress bar, or breadcrumb showing the visitor how many steps remain. Visitors who cannot see the end of the process abandon at higher rates — uncertainty about remaining effort is a direct conversion suppressor.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'CHECK_010', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'Promo code or coupon field visible on checkout page', failCondition: 'A promo code or coupon input field is visible on the checkout page. Buyers who see a promo code field and do not have a code will leave the checkout to search for one — a significant percentage do not return. Promo fields cause measurable checkout abandonment when displayed prominently.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'CHECK_011', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No post-purchase expectation set near conversion', failCondition: 'No language near the primary CTA or checkout action describes what happens immediately after payment — no mention of a confirmation email, access instructions, dispatch notification, or next steps. Uncertainty about the post-purchase experience increases hesitation at the final decision point.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'CHECK_012', category: 'Checkout & Purchase Friction', categoryNumber: 14, title: 'No abandoned checkout recovery mechanism signaled', failCondition: 'No email capture occurs at checkout entry or cart stage, and no save-cart or email-my-cart option is visible. Without capturing a contact point before checkout completion, visitors who abandon mid-checkout are unrecoverable — no win-back sequence can be triggered.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'SPEED_001', category: 'Page Speed & Technical', categoryNumber: 15, title: 'More than 5 external third-party script domains detected', failCondition: 'Page HTML references external scripts from more than 5 distinct third-party domains. Each unique domain requires a separate DNS lookup and TCP connection — loading scripts from many domains significantly increases page load time and creates multiple points of potential failure.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SPEED_002', category: 'Page Speed & Technical', categoryNumber: 15, title: 'Multiple heavy analytics and tracking tools loaded simultaneously', failCondition: 'Page loads scripts from more than two of the following simultaneously: Intercom, Drift, Hotjar, FullStory, Segment, Heap, Mixpanel, Amplitude. Each of these tools adds significant JavaScript payload and execution time — loading multiple simultaneously creates compounded performance cost that harms time-to-interactive.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SPEED_003', category: 'Page Speed & Technical', categoryNumber: 15, title: 'Images missing alt text across the page', failCondition: 'One or more img elements have empty or absent alt attributes. Missing alt text excludes screen reader users, fails visitors when images do not load, and misses keyword opportunities that contribute to image and page SEO.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SPEED_004', category: 'Page Speed & Technical', categoryNumber: 15, title: 'No lazy loading attribute on below-fold images', failCondition: 'Page contains multiple img elements but none use the loading="lazy" attribute. Without lazy loading all images load immediately on page arrival including those far below the fold, unnecessarily increasing initial data transfer and delaying time-to-interactive for above-fold content.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SPEED_005', category: 'Page Speed & Technical', categoryNumber: 15, title: 'External fonts loaded without font-display optimization', failCondition: 'Page loads external fonts via Google Fonts link tags or @font-face declarations without a font-display: swap or font-display: optional directive. Without font-display optimization the browser may show invisible text while custom fonts load, causing flash of invisible text that harms perceived performance.', mode: 'FLAW', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SPEED_006', category: 'Page Speed & Technical', categoryNumber: 15, title: 'No dns-prefetch or preconnect hints for external domains', failCondition: 'Page head contains no <link rel="dns-prefetch"> or <link rel="preconnect"> hints for external domains referenced in the page. Without these hints, the browser cannot begin DNS resolution and TCP handshake for third-party origins until they are discovered in parsing, adding measurable latency to every external resource on every page load.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SPEED_007', category: 'Page Speed & Technical', categoryNumber: 15, title: 'More than 10 distinct external domains referenced', failCondition: 'Page HTML references resources from more than 10 distinct external domains. Each unique origin requires a separate DNS lookup, TCP connection, and TLS handshake — the cumulative connection overhead for high domain counts is a significant and often overlooked page load cost that compounds on slower connections.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SPEED_008', category: 'Page Speed & Technical', categoryNumber: 15, title: 'No browser caching signal detectable in page HTML', failCondition: 'Page contains no cache-related meta tags such as Cache-Control or Expires directives in the document head, and no service worker registration script is present. Without caching signals, repeat visitors reload all assets on every visit, degrading performance for the highest-intent audience segment.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SPEED_009', category: 'Page Speed & Technical', categoryNumber: 15, title: 'Inline styles used extensively across multiple page elements', failCondition: 'More than 10 distinct elements on the page use inline style attributes for visual styling rather than class-based CSS. Extensive inline styles prevent browser style caching, force redundant recalculation on each element, and indicate the absence of a consolidated stylesheet — a pattern associated with poor overall CSS architecture and slower rendering.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SPEED_010', category: 'Page Speed & Technical', categoryNumber: 15, title: 'No critical CSS inlined in document head', failCondition: 'Page loads all CSS via external stylesheet link tags with no critical styles inlined in the document head. External stylesheets are render-blocking — without inlined critical CSS the browser must download the full stylesheet before rendering any above-fold content, directly delaying first meaningful paint.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SPEED_011', category: 'Page Speed & Technical', categoryNumber: 15, title: 'Video embeds detected without lazy load or facade pattern', failCondition: 'Page contains one or more iframe or embed elements loading third-party video players such as YouTube or Vimeo without a loading="lazy" attribute or a facade placeholder. Auto-loading third-party video players typically add 400-600KB of JavaScript and execute multiple network requests before any user interaction, significantly increasing time-to-interactive.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SPEED_012', category: 'Page Speed & Technical', categoryNumber: 15, title: 'Base64 encoded images detected inline in HTML', failCondition: 'Page HTML contains one or more base64-encoded image strings embedded directly in img src or CSS background attributes. Inline base64 images cannot be cached by the browser separately from the HTML document, inflate the initial HTML payload size, and increase parse time — particularly harmful for repeat visitors who would otherwise benefit from cached image files.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'DIFF_001', category: 'Competitive Differentiation', categoryNumber: 16, title: 'No unique mechanism stated', failCondition: 'FAIL if HERO/BODY/SECTIONS name no proprietary method, ingredient, process, or technology unique to this brand — the product reads as a commodity. PASS if a named unique mechanism appears ("our 3-stage cold-press", "patented X-engine"). Quote the named mechanism or confirm its absence.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'universal', pageType: 'any', passLabel: 'Unique mechanism named' },
  { id: 'DIFF_002', category: 'Competitive Differentiation', categoryNumber: 16, title: 'No direct or indirect competitor comparison', failCondition: 'No comparison to alternatives — no "unlike other products", no comparison table, no "why we are different" framing that positions this product against the broader competitive landscape.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'DIFF_003', category: 'Competitive Differentiation', categoryNumber: 16, title: 'No category leadership claim', failCondition: 'No claim of being first, best, most popular, most reviewed, fastest, or any superlative that establishes a category position. Category leaders convert better — even a specific leadership claim creates conversion lift.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'DIFF_004', category: 'Competitive Differentiation', categoryNumber: 16, title: 'No specific named target customer', failCondition: 'FAIL if no named customer persona, segment, or specific situation appears in HERO/BODY — the product is positioned for "everyone". PASS if a specific buyer is named and ownable. Quote the audience reference. (Differentiation lens: is the buyer specific enough to own — distinct from MSG_011\'s clarity lens.)', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'DIFF_005', category: 'Competitive Differentiation', categoryNumber: 16, title: 'Origin or sourcing story absent', failCondition: 'For products where ingredient origin or manufacturing process is a quality signal such as supplements, skincare, food, or textiles, no sourcing story, country of origin, or manufacturing standard is referenced.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'DIFF_006', category: 'Competitive Differentiation', categoryNumber: 16, title: 'No response to dominant category objection', failCondition: 'Every product category has a dominant objection such as "Does it really work?", "Is it safe?", "Will it work for me?", or "Why is it so expensive?". No content on the page directly addresses the single most common objection a potential buyer in this category would have.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'DIFF_007', category: 'Competitive Differentiation', categoryNumber: 16, title: 'No comparison table versus category alternatives', failCondition: 'No comparison table, competitor matrix, or side-by-side feature comparison exists. Buyers evaluating multiple options require a structured comparison to make a confident decision — without one, they will find the competitor\'s comparison table and use it instead.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'DIFF_008', category: 'Competitive Differentiation', categoryNumber: 16, title: 'No "why switch" or migration narrative for competitive entrants', failCondition: 'No narrative addresses why a visitor should switch from their current solution. Without a switching story, prospects already using a competitor have no reason to consider the transition cost justified and will default to inertia.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'DIFF_009', category: 'Competitive Differentiation', categoryNumber: 16, title: 'No founder or team expertise credential', failCondition: 'No founder credential, team expertise signal, or domain authority statement appears on the page. In markets where expertise is a purchase criterion, the absence of a credibility anchor for the people behind the product is a meaningful trust gap that undifferentiated competitors can exploit.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'DIFF_010', category: 'Competitive Differentiation', categoryNumber: 16, title: 'Differentiation claims match competitor language exactly', failCondition: 'FAIL if the page\'s stated differentiators are interchangeable category clichés — "easy to use", "all-in-one", "saves time", "best-in-class" — that every competitor also claims (see HERO/BODY/SECTIONS). PASS if the differentiation is specific and ownable. Quote the cliché differentiator.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'DIFF_011', category: 'Competitive Differentiation', categoryNumber: 16, title: 'No third-party validation or industry recognition cited', failCondition: 'No industry award, analyst recognition, press mention, or third-party validation is cited. External endorsements function as credibility amplifiers that a brand cannot generate internally — their absence signals the product has not yet earned independent market recognition.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'DIFF_012', category: 'Competitive Differentiation', categoryNumber: 16, title: 'Unique mechanism named but mechanism of action unexplained', failCondition: 'FAIL if a proprietary method/ingredient/technology IS named but HERO/BODY/SECTIONS never explain how it works or why it is superior. PASS if the named mechanism\'s action is explained, OR if no mechanism is named (that absence is DIFF_001, not here). Quote the named-but-unexplained mechanism.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SPEC_001', category: 'Specificity & Claim Quality', categoryNumber: 17, title: 'Results claims contain no timeframe', failCondition: 'FAIL if a results claim in HERO/BODY ("helps with energy", "improves skin", "increases focus") carries no timeframe for when results appear. PASS if a timeframe is attached ("in 2 weeks"), or no results claims are made. Quote the claim and note the missing timeframe.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SPEC_003', category: 'Specificity & Claim Quality', categoryNumber: 17, title: 'Guarantee terms are not specific', failCondition: 'A guarantee is mentioned but its terms are vague — no specific number of days, no explanation of the refund process, no clarity on what qualifies. Specific guarantee terms convert better than vague assurances.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SPEC_004', category: 'Specificity & Claim Quality', categoryNumber: 17, title: 'CTA does not specify what happens after clicking', failCondition: 'CTA text or surrounding microcopy does not tell the visitor exactly what happens when they click. Uncertainty about the next step reduces click-through rate.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SPEC_005', category: 'Specificity & Claim Quality', categoryNumber: 17, title: 'Ingredient or feature claims not quantified', failCondition: 'FAIL if, for a product where dosage/quantity/spec matters, ingredient amounts or feature specs in BODY/SECTIONS are absent or vague ("contains antioxidants" with no amount). PASS if quantified ("500mg", "10× faster"). Quote the unquantified claim.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SPEC_006', category: 'Specificity & Claim Quality', categoryNumber: 17, title: 'Social proof numbers are suspiciously round', failCondition: 'Customer counts or review numbers are suspiciously round such as "10,000 customers" or "500 reviews" suggesting they are estimates rather than real figures. Specific numbers are perceived as more credible because they appear real and counted.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SPEC_007', category: 'Specificity & Claim Quality', categoryNumber: 17, title: 'No specific customer count or community size stated', failCondition: 'No specific customer count, user number, or community size is cited. A named customer volume — "over 14,300 businesses" rather than "thousands of businesses" — is one of the highest-credibility proof signals available and its absence removes a key conviction lever.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SPEC_008', category: 'Specificity & Claim Quality', categoryNumber: 17, title: 'Outcome claims use percentage without a baseline', failCondition: 'FAIL if BODY/HERO states a percentage-improvement claim ("increases conversion by 30%") with no baseline, sample size, or study context. PASS if the percentage has a reference point, or no percentage claims exist. Quote the percentage claim.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'SPEC_009', category: 'Specificity & Claim Quality', categoryNumber: 17, title: 'Claims use hedging language that signals uncertainty', failCondition: 'FAIL if claims in HERO/BODY use hedging qualifiers — "up to", "as much as", "can help", "may improve" — that signal best-case rather than typical results. PASS if claims are stated plainly without hedges. Quote the hedged phrase.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'SPEC_010', category: 'Specificity & Claim Quality', categoryNumber: 17, title: 'No named customer case study or detailed success story', failCondition: 'No named customer case study, detailed success story, or outcome-linked customer reference exists. Case studies are the highest-conviction proof format available and their absence forces buyers to estimate results without evidence, reducing confidence to convert.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'RET_001', category: 'Return Visitor & Retention', categoryNumber: 18, title: 'No account dashboard or logged-in state signal detected', failCondition: 'Page HTML contains no signals of a member account area, login portal, or dashboard destination — no links to "My Account", "Dashboard", "Order History", or equivalent. Visitors have no indication that an account relationship exists beyond the first purchase.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'RET_002', category: 'Return Visitor & Retention', categoryNumber: 18, title: 'No personalization or recently viewed signal on product pages', failCondition: 'No recently viewed items, personalized recommendations, or returning visitor content is detectable. Return visitor experience is identical to first visit, offering no recognition or continuity.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'RET_003', category: 'Return Visitor & Retention', categoryNumber: 18, title: 'No win-back or re-engagement language visible', failCondition: 'No welcome-back messaging, returning customer incentive, or re-engagement offer is present. Site treats all visitors identically regardless of purchase history, missing the opportunity to recover lapsed buyers.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'RET_004', category: 'Return Visitor & Retention', categoryNumber: 18, title: 'No subscription or auto-replenish option for consumable products', failCondition: 'For consumable products where repeat purchase is expected, no subscription, auto-ship, or auto-replenish option is presented. One-time purchase is the only path, eliminating the most reliable retention mechanism for consumable goods.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'RET_005', category: 'Return Visitor & Retention', categoryNumber: 18, title: 'No membership or VIP tier benefits described', failCondition: 'No membership tier, VIP status, or loyalty tier benefits are described anywhere on the page. Without a progression pathway or tiered reward, visitors have no reason to consolidate purchases with this brand over alternatives.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'RET_006', category: 'Return Visitor & Retention', categoryNumber: 18, title: 'No community signal — no forum, user group, or peer network mentioned', failCondition: 'No community forum, customer group, peer network, or social community is referenced on the page. Community belonging is a retention driver that increases switching cost — its absence removes a key reason for ongoing engagement beyond individual purchases.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  // REMOVED: RET_007 — not evaluatable from page scan
  { id: 'RET_008', category: 'Return Visitor & Retention', categoryNumber: 18, title: 'No loyalty or points program visible for repeat purchases', failCondition: 'No loyalty points program, rewards accumulation mechanism, or repeat-purchase incentive is communicated on the page. For brands where repeat purchase rate drives profitability, a loyalty program is the primary structural tool for increasing LTV — its absence means each repeat purchase must be re-won on price or promotion alone.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'RET_009', category: 'Return Visitor & Retention', categoryNumber: 18, title: 'No post-purchase content or onboarding path signaled', failCondition: 'Page provides no signal of what happens after purchase — no onboarding email sequence, no getting-started guide, no first-use tutorial, no customer success path described. Buyers who cannot see a path from purchase to successful use evaluate the product as a higher-risk purchase, particularly for complex or high-investment items.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  // REMOVED: RET_010 — not evaluatable from page scan
  { id: 'ACCESS_001', category: 'Accessibility & Inclusion', categoryNumber: 19, title: 'Text contrast ratio insufficient', failCondition: 'Based on visual analysis, text color against its background does not meet minimum contrast standards. Low contrast excludes visitors with visual impairments and is a conversion failure for all visitors in bright ambient light conditions.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'ACCESS_002', category: 'Accessibility & Inclusion', categoryNumber: 19, title: 'No alt text on product or hero images', failCondition: 'Key images have no descriptive alt text. This excludes screen reader users, fails visitors when images do not load, and misses SEO keyword opportunities.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'ACCESS_003', category: 'Accessibility & Inclusion', categoryNumber: 19, title: 'Forms have no visible labels', failCondition: 'Input fields in any form use placeholder text as the only label with no persistent visible label above or beside the field. Placeholder-only labels disappear when the user begins typing, creating confusion particularly for users with cognitive impairments.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'ACCESS_004', category: 'Accessibility & Inclusion', categoryNumber: 19, title: 'Color used as only means of conveying information', failCondition: 'Any information on the page is communicated through color alone with no text or icon backup — for example required form fields shown only in red, or sale prices distinguished only by color change. 8% of men have color vision deficiency — color-only communication excludes them entirely.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'ACCESS_005', category: 'Accessibility & Inclusion', categoryNumber: 19, title: 'No visible focus indicator on interactive elements', failCondition: 'Interactive elements — links, buttons, and form inputs — show no visible focus ring or highlight when navigated to by keyboard. CSS outline:none or outline:0 applied globally removes the browser default focus indicator. Keyboard users navigating without a mouse cannot determine their current position on the page, making the site effectively unusable for this audience.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'ACCESS_006', category: 'Accessibility & Inclusion', categoryNumber: 19, title: 'Form inputs have no associated label element', failCondition: 'One or more form input fields have no associated <label> element — no label with a matching for attribute pointing to the input id, and no aria-label attribute. Screen readers cannot announce what the field requires when a label is absent, making the form unusable for visually impaired users.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'ACCESS_007', category: 'Accessibility & Inclusion', categoryNumber: 19, title: 'No skip navigation link at top of document', failCondition: 'Page contains no skip-to-main-content or skip-navigation link as the first focusable element in the document. Keyboard-only and screen reader users must tab through the entire navigation menu on every page load before reaching main content — a significant barrier for users who cannot use a mouse.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'ACCESS_008', category: 'Accessibility & Inclusion', categoryNumber: 19, title: 'ARIA labels absent on icon-only buttons', failCondition: 'Page contains one or more button or anchor elements that contain only an icon — SVG, image, or icon font character — with no visible text and no aria-label or aria-labelledby attribute. Icon-only interactive elements are completely invisible to screen reader users who cannot determine the button\'s purpose.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'ACCESS_009', category: 'Accessibility & Inclusion', categoryNumber: 19, title: 'No lang attribute on HTML element', failCondition: 'The root <html> element has no lang attribute. Screen readers use the lang attribute to select the correct speech synthesis engine and pronunciation rules — without it, content may be read aloud with incorrect pronunciation, making the page difficult or impossible to understand for screen reader users.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'ACCESS_010', category: 'Accessibility & Inclusion', categoryNumber: 19, title: 'Links use non-descriptive text — "click here", "read more", or "learn more"', failCondition: 'One or more anchor elements contain only generic link text such as "click here", "read more", "learn more", or "here". Screen reader users navigating by links hear only the link text out of context — non-descriptive link text provides no information about the destination and violates basic accessibility link-text guidelines.', mode: 'FLAW', severity: 'Medium', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'ACCESS_011', category: 'Accessibility & Inclusion', categoryNumber: 19, title: 'Error messages not associated with form fields via aria-describedby', failCondition: 'Form validation error messages exist in the HTML but are not linked to their corresponding input fields via aria-describedby. Screen readers announce form errors only when they are programmatically associated with the field — unlinked error messages are not read aloud when the field receives focus, leaving users with no indication of what went wrong.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'ACCESS_012', category: 'Accessibility & Inclusion', categoryNumber: 19, title: 'Icon-based navigation has no visible text label', failCondition: 'Navigation items use icons alone with no visible text label and no accessible tooltip or aria-label attribute. Icon meanings are not universal — navigation that relies entirely on icon recognition excludes unfamiliar users and fails accessibility standards that require text alternatives for non-text content.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },

  // ── Universal & Cross-Vertical (21) ──────────────────────────────────────
  { id: 'UNIV_001', category: 'Universal & Cross-Vertical', categoryNumber: 20, title: 'No video content present', failCondition: 'No product demo video, explainer video, testimonial video, or any video content detected on the page. Video increases time on site and conversion rates across all site types.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'UNIV_002', category: 'Universal & Cross-Vertical', categoryNumber: 20, title: 'No announcement bar or offer strip in page header', failCondition: 'Page header HTML contains no announcement bar, promotional strip, or offer banner pattern such as class names announcement, banner, or top-bar. Header announcement bars are high-visibility real estate that communicate free shipping thresholds, active promotions, or time-sensitive offers to every visitor regardless of landing page.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'UNIV_003', category: 'Universal & Cross-Vertical', categoryNumber: 20, title: 'Visitor cannot orient within 3 seconds above the fold', failCondition: 'The above-fold content does not simultaneously communicate what the site offers, who it is for, and what action to take next. A visitor landing cold cannot answer all three questions within 3 seconds of arrival.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'UNIV_004', category: 'Universal & Cross-Vertical', categoryNumber: 20, title: 'No real-time support channel visible', failCondition: 'No live chat widget, chatbot, or immediately visible real-time support option is present. For high-consideration or complex purchases, the absence of accessible real-time help drives abandonment at the decision stage.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'UNIV_006', category: 'Universal & Cross-Vertical', categoryNumber: 20, title: 'No international or currency signals for global audiences', failCondition: 'No currency selector, international shipping notice, or localization signal is present for visitors outside the primary market. For brands with global traffic, absence of localization signals creates purchase friction for non-domestic visitors.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'UNIV_007', category: 'Universal & Cross-Vertical', categoryNumber: 20, title: 'Cookie consent banner obstructs page content', failCondition: 'A cookie consent banner or GDPR notice blocks significant page content, overlays the hero, or forces interaction before the visitor can see the primary value proposition. Cookie notices must not obstruct the conversion experience.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'UNIV_008', category: 'Universal & Cross-Vertical', categoryNumber: 20, title: 'No site search on multi-page site', failCondition: 'Site appears to have more than 10 pages or products but no site search functionality is present in the navigation or header. Visitors who cannot locate content quickly abandon rather than browse.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'UNIV_009', category: 'Universal & Cross-Vertical', categoryNumber: 20, title: 'Contact information not visible without scrolling', failCondition: 'No phone number, email address, or direct contact link is visible above the fold or in a persistent header. Visitors who cannot quickly verify a human is reachable lose trust, particularly for first-time purchases.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'UNIV_011', category: 'Universal & Cross-Vertical', categoryNumber: 20, title: 'Social media links navigate away without opening a new tab', failCondition: 'Social media icons in header or footer open in the same browser tab, sending visitors away from the site with no return path. External links must open in a new tab to preserve the active conversion session.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },

  // ── SaaS-Specific (22) ────────────────────────────────────────────────────
  { id: 'SAAS_001', category: 'SaaS-Specific', categoryNumber: 21, title: 'Signup or onboarding flow requires too many steps', failCondition: 'The signup, registration, or onboarding flow requires more than 3 fields or steps before delivering value. SaaS products that gate value behind lengthy signups see sharply higher activation abandonment.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'SAAS_002', category: 'SaaS-Specific', categoryNumber: 21, title: 'Free trial terms not clearly stated near CTA', failCondition: 'A free trial is offered but the duration, credit card requirement, and what occurs at trial end are not clearly stated adjacent to the signup CTA. Ambiguous trial terms reduce signup rates and generate post-trial refund disputes.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'saas', pageType: 'any', passLabel: 'Trial terms clear near CTA' },
  { id: 'SAAS_003', category: 'SaaS-Specific', categoryNumber: 21, title: 'No integration or compatibility signals', failCondition: 'No mention of compatible platforms, integrations, or supported technology stack. SaaS buyers must confirm a tool works within their existing environment before evaluating it further — absence of this information stalls the evaluation.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'SAAS_004', category: 'SaaS-Specific', categoryNumber: 21, title: 'Pricing tier differences not clearly differentiated', failCondition: 'FAIL if PRICING shows multiple tiers but the meaningful difference between them is unclear — overlapping or blurry feature lists, no distinguishing value per tier. PASS if each tier\'s distinct value is clear. SKIP if no tiers are shown. Cite the tier names/features and the unclear distinction.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'SAAS_005', category: 'SaaS-Specific', categoryNumber: 21, title: 'No product screenshot or interface preview above fold', failCondition: 'No product screenshot, UI preview, or demo video is visible in the hero section or above the fold. SaaS visitors need to see the product interface before they will invest time in a trial or demo request.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any', passLabel: 'Product UI visible above fold' },
  { id: 'SAAS_006', category: 'SaaS-Specific', categoryNumber: 21, title: 'No audience segmentation or "who this is for" signal', failCondition: 'FAIL if HERO/BODY/SECTIONS present the product with no named audience, role, or use-case ("who this is for"). PASS if a specific audience or use-case is named. Quote the audience signal or confirm its absence.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'SAAS_007', category: 'SaaS-Specific', categoryNumber: 21, title: 'No freemium or free plan tier mentioned', failCondition: 'No free plan, freemium tier, or permanently free option is communicated on the page. SaaS buyers increasingly expect a no-credit-card-required entry point before committing to a paid subscription — the absence of a free tier removes the lowest-friction evaluation path and reduces top-of-funnel conversion for cold traffic.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'SAAS_008', category: 'SaaS-Specific', categoryNumber: 21, title: 'No security or compliance badge visible on page', failCondition: 'Page contains no security certification badges, compliance logos such as SOC 2, GDPR, HIPAA, or ISO 27001, or data security assurance statements visible on the landing page. For products that handle user data, credentials, or sensitive business information, the absence of security signals is a significant conversion barrier for enterprise and security-conscious buyers evaluating vendor risk.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'SAAS_009', category: 'SaaS-Specific', categoryNumber: 21, title: 'No customer logo wall visible above the fold', failCondition: 'No recognizable customer logos, brand names, or "trusted by" section is visible in the hero area or above the fold. SaaS buyers make vendor decisions faster when they see that companies similar to their own already use the product — a logo wall above the fold reduces cold-traffic skepticism before the visitor has read a single claim.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'SAAS_010', category: 'SaaS-Specific', categoryNumber: 21, title: 'No API or integration ecosystem signal', failCondition: 'Page makes no reference to an API, webhook capability, native integrations, or supported platforms. Technical buyers and product managers evaluating SaaS tools prioritize integrations as a selection criterion — a product that does not communicate its ecosystem compatibility stalls evaluation before it begins for buyers with existing toolstacks.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'SAAS_011', category: 'SaaS-Specific', categoryNumber: 21, title: 'No cancellation terms visible — subscription lock-in risk not addressed', failCondition: 'Page offers a subscription product but contains no language about cancellation — no "cancel anytime", no minimum contract term, no cancellation process description. Buyers who cannot confirm they can exit freely before committing perceive higher lock-in risk and convert at lower rates, particularly for monthly plans where flexibility is a primary purchase driver.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'SAAS_012', category: 'SaaS-Specific', categoryNumber: 21, title: 'Pricing page linked from navigation but no price range visible on homepage', failCondition: 'Navigation includes a link to a pricing page but the homepage contains no pricing range, starting price, or tier indicator. Visitors who cannot self-qualify on price from the homepage must make an extra click before knowing if the product fits their budget — adding a navigation step that creates dropout before the pricing page is reached.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'SAAS_013', category: 'SaaS-Specific', categoryNumber: 21, title: 'No pricing tier comparison table visible', failCondition: 'No pricing tier comparison table or feature matrix differentiates plan options. Buyers evaluating SaaS plans need to self-select the right tier — without a structured comparison they default to the lowest tier or abandon the decision entirely.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'SAAS_014', category: 'SaaS-Specific', categoryNumber: 21, title: 'No "most popular" or recommended plan indicated', failCondition: 'Pricing section shows multiple tiers with no "most popular", "recommended", or "best value" indicator on any plan. Without a social proof anchor on one tier, buyers face a multi-way decision with no default — increasing cognitive load at the most critical conversion step.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'SAAS_015', category: 'SaaS-Specific', categoryNumber: 21, title: 'No annual discount or billing period savings shown', failCondition: 'Monthly pricing is displayed with no annual billing option or annual discount percentage visible. Annual pre-pay is the primary ARR acceleration lever for SaaS — its absence removes the highest-value conversion path from every pricing interaction.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'SAAS_016', category: 'SaaS-Specific', categoryNumber: 21, title: 'Seat or usage limits not clearly stated per tier', failCondition: 'FAIL if PRICING tiers are shown but seat counts, usage caps, or rate limits are not stated per tier. PASS if per-tier limits are stated. SKIP if no pricing tiers are shown. Cite the tier feature lines and the missing limit.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'saas', pageType: 'any' },

  // ── E-commerce Specific (23) ──────────────────────────────────────────────
  { id: 'ECOM_001', category: 'E-commerce Specific', categoryNumber: 22, title: 'No size guide or fit information for sized products', failCondition: 'For products with sizing such as apparel, footwear, or accessories, no size guide, measurement chart, or fit recommendation is visible on the product page. Sizing uncertainty is one of the primary drivers of both purchase abandonment and return events.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'ECOM_002', category: 'E-commerce Specific', categoryNumber: 22, title: 'Return policy not visible near add-to-cart', failCondition: 'Return policy is buried in the footer or a separate page with no summary visible near the add-to-cart button or pricing. Return policy visibility near the purchase decision directly correlates with purchase confidence on product pages.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'ECOM_003', category: 'E-commerce Specific', categoryNumber: 22, title: 'No stock level or inventory urgency signal', failCondition: 'No low-stock indicator, inventory count, or real-inventory scarcity signal is present on product pages. Stock-based urgency increases purchase rate without requiring discount promotions.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'ECOM_004', category: 'E-commerce Specific', categoryNumber: 22, title: 'No gift wrapping or gifting option', failCondition: 'No gift wrapping, gift message, or gifting-oriented option is visible on product or cart pages. Gifting options increase average order value and unlock a second purchase segment — buyers purchasing for others.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'ECOM_005', category: 'E-commerce Specific', categoryNumber: 22, title: 'Shipping timeframe not communicated', failCondition: 'No estimated delivery date, dispatch timeline, or shipping timeframe is visible on the product page or near the add-to-cart button. Delivery uncertainty is a primary abandonment cause when purchase timing matters to the buyer.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },
  { id: 'ECOM_006', category: 'E-commerce Specific', categoryNumber: 22, title: 'No product comparison feature for similar SKUs', failCondition: 'For sites with multiple similar products or variants, no comparison feature or side-by-side view exists. Shoppers who cannot compare products on-site go to competitor sites to make the comparison and often do not return.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'ecommerce', pageType: 'any' },

  // ── Agency & Service (24) ─────────────────────────────────────────────────
  { id: 'SERV_001', category: 'Agency & Service', categoryNumber: 23, title: 'No process or how-it-works explanation', failCondition: 'The engagement process — from initial contact through project delivery — is not explained anywhere on the site. Service buyers need to understand what working together looks like before they will commit to an inquiry or discovery call.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'service', pageType: 'any' },
  { id: 'SERV_002', category: 'Agency & Service', categoryNumber: 23, title: 'Case studies present but lack measurable outcomes', failCondition: 'Case studies or portfolio examples exist but contain no specific metrics, percentage improvements, revenue figures, or quantified client outcomes. Vague case studies are perceived as less credible than ones with specific numbers.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'service', pageType: 'any' },
  { id: 'SERV_003', category: 'Agency & Service', categoryNumber: 23, title: 'No response time or inquiry turnaround signal', failCondition: 'No indication of how quickly inquiries are responded to — no "reply within 24 hours", "same-day response", or equivalent commitment. For service businesses, response speed is a key trust and vendor-selection factor.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'service', pageType: 'any' },
  { id: 'SERV_004', category: 'Agency & Service', categoryNumber: 23, title: 'No minimum engagement or pricing range indicated', failCondition: 'No pricing range, minimum project size, or engagement starting point is communicated anywhere on the site. The absence of any pricing signal forces potential clients to invest discovery time only to find budget misalignment.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'service', pageType: 'any' },
  { id: 'SERV_005', category: 'Agency & Service', categoryNumber: 23, title: 'Team credentials or expertise not visible', failCondition: 'No team page, named individuals, professional credentials, years of experience, or relevant expertise signals are present. For service businesses, buyers are fundamentally buying the people — teams that are invisible reduce conversion.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'service', pageType: 'any' },
  { id: 'SERV_006', category: 'Agency & Service', categoryNumber: 23, title: 'No discovery call or consultation CTA above fold', failCondition: 'The primary conversion action for a service business — a discovery call, consultation booking, or intake form — is not visible in the hero section or above the fold. The most important action the site needs visitors to take is buried below the scroll threshold.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'service', pageType: 'any' },

  // ── Conversion Path Expansion (25) ───────────────────────────────────────
  { id: 'CONV_001', category: 'Conversion Path Expansion', categoryNumber: 24, title: 'No self-selection path for visitor routing', failCondition: 'Visitor cannot route themselves to the most relevant product or plan — no "I am a..." selector, quiz entry, use-case filter, or persona-based navigation path exists. Visitors who cannot quickly confirm the product fits their specific need default to competitors who make this determination easier.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CONV_002', category: 'Conversion Path Expansion', categoryNumber: 24, title: 'No upsell or cross-sell path at key conversion moments', failCondition: 'No upsell offer, order bump, or cross-sell recommendation appears at key conversion moments — cart, checkout, or post-purchase confirmation. These touchpoints are the highest-ROI moments for revenue expansion with zero additional acquisition cost.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CONV_003', category: 'Conversion Path Expansion', categoryNumber: 24, title: 'No plan comparison or "which is right for me" guidance', failCondition: 'No comparison tool, decision guide, or "which plan is right for me" copy exists to help visitors select the correct product or tier. Visitors who cannot self-qualify between options stall at the decision point or choose incorrectly and churn.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CONV_004', category: 'Conversion Path Expansion', categoryNumber: 24, title: 'No waitlist or coming-soon mechanism for unavailable products', failCondition: 'No waitlist signup, coming-soon notification, or pre-order option exists for out-of-stock or unreleased products. Visitors who arrive for unavailable items are given no path to capture demand — future purchase intent is lost entirely.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CONV_005', category: 'Conversion Path Expansion', categoryNumber: 24, title: 'No live inventory or urgency signal at point of conversion', failCondition: 'No stock level indicator, real-time inventory count, or scarcity signal is present at the conversion point. Without urgency grounding in real inventory, visitors feel no time pressure and defer decisions indefinitely.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CONV_006', category: 'Conversion Path Expansion', categoryNumber: 24, title: 'No co-browsing or guided selling option', failCondition: 'No live chat, guided selling flow, product recommendation quiz, or assisted selection path exists. Visitors must navigate product selection alone with no human or automated guidance, increasing drop-off for complex purchase decisions.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CONV_007', category: 'Conversion Path Expansion', categoryNumber: 24, title: 'No save-for-later or wishlist mechanism', failCondition: 'No wishlist, save-for-later, or favorites mechanism exists. Visitors who are interested but not ready to purchase today have no way to bookmark intent — return purchase probability drops significantly when visitors must rediscover the product from scratch on a future visit.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CONV_008', category: 'Conversion Path Expansion', categoryNumber: 24, title: 'No buy-now-pay-later or installment option visible near primary CTA', failCondition: 'No BNPL, installment plan, or financing option is visible near the primary CTA or pricing display. For purchases above $50, the absence of a deferred payment option eliminates a segment of budget-conscious buyers who would convert with an installment path.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CONV_009', category: 'Conversion Path Expansion', categoryNumber: 24, title: 'No demo or interactive preview available without signup', failCondition: 'No product demo, interactive preview, sandbox environment, or feature tour is available to visitors without first creating an account. Requiring signup before showing value increases top-of-funnel abandonment — buyers who cannot see the product working before committing personal information opt out rather than risk a wasted signup.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CONV_010', category: 'Conversion Path Expansion', categoryNumber: 24, title: 'No trial-to-paid conversion path visible on pricing page', failCondition: 'Pricing page shows no trial-to-paid upgrade path, no CTA from within the trial interface, and no frictionless plan selection for trial users. SaaS products without a defined in-product or on-page upgrade path rely entirely on outbound follow-up to convert trials — missing the highest-intent conversion moment.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'saas', pageType: 'any' },
  { id: 'CONV_011', category: 'Conversion Path Expansion', categoryNumber: 24, title: 'No social or SSO login option at signup', failCondition: 'Signup form requires manual email and password entry with no social login option — no Google, GitHub, LinkedIn, or SSO path. Every additional field in the signup form reduces completion rate; social login that eliminates the form entirely consistently increases signup conversion for tools with professional audiences. This check only fires when a signup or registration form is visible on the scanned page.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'CONV_012', category: 'Conversion Path Expansion', categoryNumber: 24, title: 'No referral or word-of-mouth mechanism visible', failCondition: 'No referral program, share incentive, "invite a teammate", or word-of-mouth mechanism is visible on the site. For products with network effects or team-based use, the absence of a referral path misses the highest-quality acquisition channel — existing customers recommending to known prospects — and eliminates viral loop potential entirely.', mode: 'GAP', severity: 'Low', requiresEvidence: false, siteType: 'universal', pageType: 'any' },

  // ── Narrative Flow (26) ───────────────────────────────────────────────────
  { id: 'NARR_001', category: 'Narrative Flow', categoryNumber: 25, title: 'Subheadline restates headline with no progression', failCondition: 'FAIL if the HERO Subheadline merely restates the Headline in different words with no progression — it adds no new problem, proof, mechanism, or specificity. PASS if the subheadline advances the message. SKIP only if no subheadline exists (that absence is HERO_004). Quote both Headline and Subheadline.', mode: 'FLAW', severity: 'High', requiresEvidence: true, siteType: 'universal', pageType: 'any' },
  { id: 'NARR_002', category: 'Narrative Flow', categoryNumber: 25, title: 'Social proof appears before product comprehension is established', failCondition: 'FAIL if, in the H2/SECTIONS document-order sequence, a testimonials/reviews/logos section appears before any section that explains what the product is or does — trust before comprehension. PASS if comprehension precedes proof. Cite the heading sequence showing proof ahead of the explanation.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NARR_003', category: 'Narrative Flow', categoryNumber: 25, title: 'No problem framing between headline and features', failCondition: 'FAIL if the H2/SECTIONS sequence goes from the hero headline straight into features with no problem / why-you-need-this section between them. PASS if a problem bridge precedes the features. Cite the opening heading sequence (hero → first sections).', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NARR_004', category: 'Narrative Flow', categoryNumber: 25, title: 'CTA destination does not match the hero offer', failCondition: 'Hero CTA promises one outcome but the destination delivers a different experience. Mismatched CTA destination breaks the narrative contract with the visitor and destroys purchase intent at the moment of highest motivation.', mode: 'FLAW', severity: 'Critical', requiresEvidence: false, siteType: 'universal', pageType: 'any', passLabel: 'CTA destination matches offer' },
  { id: 'NARR_005', category: 'Narrative Flow', categoryNumber: 25, title: 'Page sections do not build logically toward the CTA', failCondition: 'FAIL if the H2/SECTIONS document-order sequence does not progress toward the conversion action — sections read as arbitrary or out of persuasive order. PASS if each section sets up the next and the sequence builds to the CTA. Cite the heading sequence and the break in logic.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NARR_006', category: 'Narrative Flow', categoryNumber: 25, title: 'Hero presents product without framing the problem it solves', failCondition: 'FAIL if the HERO Headline/Subheadline state what the product is but never frame the problem it solves — no emotional hook before the offer. PASS if the hero names the problem or desire. Quote the HERO text.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NARR_007', category: 'Narrative Flow', categoryNumber: 25, title: 'Proof appears after CTA rather than before it', failCondition: 'FAIL if, in the H2/SECTIONS sequence, the first proof section (testimonials/reviews/logos) appears only in the final third with no proof in the first half — proof arrives after the visitor has passed the primary decision point. PASS if proof appears in the first half or before the main CTA. Cite the heading sequence and PAGE STRUCTURE.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NARR_008', category: 'Narrative Flow', categoryNumber: 25, title: 'Page has no clear narrative arc from attention to action', failCondition: 'FAIL if the page shows no deliberate attention→interest→desire→action arc across the HERO and the H2/SECTIONS sequence — it is a flat feature dump with no emotional progression. PASS if a clear AIDA build is present. Cite the overall sequence. (Holistic check: its parts are NARR_003/006 problem, NARR_002/007 proof, NARR_005/012 CTA buildup.)', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any', passLabel: 'Clear AIDA narrative arc' },
  { id: 'NARR_009', category: 'Narrative Flow', categoryNumber: 25, title: 'Value proposition and pricing appear in reverse order', failCondition: 'FAIL if a PRICING section/heading appears in the H2/SECTIONS sequence before any value/benefit/proof section has established desire. PASS if value precedes price. SKIP if no pricing is shown on the page. Cite the heading sequence showing price ahead of value.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NARR_010', category: 'Narrative Flow', categoryNumber: 25, title: 'Page opens with brand story rather than visitor problem', failCondition: 'FAIL if the HERO and first H2/SECTIONS open with the brand\'s story/history/"about us" rather than the visitor\'s problem (COPY FRAMING brand-voice leading reinforces this). PASS if the opening leads with the visitor\'s problem. Cite the opening sequence.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NARR_011', category: 'Narrative Flow', categoryNumber: 25, title: 'Page opens with navigation or admin content before value proposition', failCondition: 'First visible content encountered by a new visitor is navigation, an announcement bar, a cookie notice, or a promotional banner rather than a headline or value statement. Every second of attention spent on administrative content before the value proposition is a second of motivation lost.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NARR_012', category: 'Narrative Flow', categoryNumber: 25, title: 'CTA appears before sufficient value has been communicated', failCondition: 'FAIL if the only value context before the first CTA is the headline alone — the HERO carries a CTA but no Subheadline and no benefit/proof, and no value section precedes it. PASS if meaningful value or proof precedes the first CTA. Cite the HERO block and the opening sequence.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NARR_013', category: 'Narrative Flow', categoryNumber: 25, title: 'Heading hierarchy broken — H3 or H4 appears before first H1', failCondition: 'The page contains an H3 or H4 element that appears in document order before the first H1. A broken heading hierarchy signals disorganized content structure, impairs screen reader navigation, and undermines SEO signals that communicate page topic hierarchy to search engines.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NARR_014', category: 'Narrative Flow', categoryNumber: 25, title: 'Page ends without a final CTA', failCondition: 'Page ends with footer links, legal text, or passive content with no final compelling CTA. Visitors who scroll to the bottom are the most engaged segment — failing to capture them at this point is a direct conversion miss.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'NARR_015', category: 'Narrative Flow', categoryNumber: 25, title: 'Page uses passive voice throughout — no direct address to the visitor', failCondition: 'FAIL if copy is predominantly brand/third-person framing with little direct second-person address — COPY FRAMING shows customer-voice ("you/your") near zero or far below brand-voice ("we/our"). PASS if the page speaks directly to "you". Cite the COPY FRAMING counts.', mode: 'FLAW', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },

  // ── Objection Handling (27) ───────────────────────────────────────────────
  { id: 'OBJ_001', category: 'Objection Handling', categoryNumber: 26, title: 'No FAQ section addressing purchase hesitations', failCondition: 'No FAQ section exists that addresses purchase-blocking hesitations — commitment fears, cancellation terms, what happens after signup, or "is this right for me" concerns. A FAQ covering only product features without handling emotional objections that prevent purchase is insufficient.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'OBJ_002', category: 'Objection Handling', categoryNumber: 26, title: 'No risk reversal visible near CTA', failCondition: 'No risk-reversal mechanism — money-back guarantee, free trial, no credit card required, or satisfaction promise — appears near the primary CTA. Visitors at the point of conversion weigh perceived risk; without a visible risk-reversal signal adjacent to the action step, downside risk suppresses conversion.', mode: 'GAP', severity: 'Critical', requiresEvidence: false, siteType: 'universal', pageType: 'any', passLabel: 'Risk reversal near CTA' },
  { id: 'OBJ_003', category: 'Objection Handling', categoryNumber: 26, title: 'No explicit positioning against alternatives or competitors', failCondition: 'Page makes no attempt to explain why a visitor should choose this product over alternatives — no "unlike other solutions", no competitor comparison, no "why us over X" framing. Buyers always compare; a page that does not participate in this comparison cedes that decision to the competitor.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'OBJ_004', category: 'Objection Handling', categoryNumber: 26, title: 'Pricing objection not addressed with ROI or value framing', failCondition: 'Pricing is displayed but no ROI language, "pays for itself" framing, cost-of-inaction comparison, or value context appears near the price point. Price without value framing allows cost to dominate the decision rather than return on investment.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'OBJ_005', category: 'Objection Handling', categoryNumber: 26, title: 'Effort or setup objection not addressed', failCondition: 'No signal communicates how quickly a new user can get started — no "live in X minutes", "setup in under an hour", "no technical skills required", or equivalent time-to-value claim. Fear of effort and complexity is a primary conversion blocker that requires proactive neutralization.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any', passLabel: 'Time-to-value clearly stated' },
  { id: 'OBJ_006', category: 'Objection Handling', categoryNumber: 26, title: 'No "who this is for / not for" clarity signal', failCondition: 'Page provides no explicit signals about who the product is designed for and who it is not suited for. Without ICP-qualification language, high-fit prospects cannot confirm the product is built for their specific situation and low-fit buyers proceed to waste everyone\'s time — both outcomes reduce effective conversion rate.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'OBJ_007', category: 'Objection Handling', categoryNumber: 26, title: 'Trust objections not addressed — no security, data handling, or compliance signals', failCondition: 'Page contains no signals addressing trust-based objections — no security certifications, data handling statements, compliance badges such as SOC 2, GDPR, or HIPAA, or data privacy assurances where these are relevant to the buyer. For products handling sensitive data or requiring access credentials, unaddressed trust objections silently eliminate high-intent prospects.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'OBJ_008', category: 'Objection Handling', categoryNumber: 26, title: 'No third-party credibility signal — press, investors, accelerators, or awards absent', failCondition: 'No third-party credibility markers are present — no press coverage, investor names, accelerator badges such as Y Combinator or Techstars, or industry award recognition. Third-party validation provides credibility that self-made claims cannot achieve and is especially persuasive for visitors unfamiliar with the brand.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'OBJ_009', category: 'Objection Handling', categoryNumber: 26, title: 'No exit path for visitors not ready to purchase', failCondition: 'Page offers no alternative for visitors who are not ready to convert — no email capture, free tier, content download, newsletter, or low-commitment option. Visitors who are not purchase-ready but could convert later are given no path to remain in the funnel and are lost entirely.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },

  // ── Offer Clarity (28) ────────────────────────────────────────────────────
  { id: 'OFC_001', category: 'Offer Clarity', categoryNumber: 27, title: 'Offer or product name is absent or unclear', failCondition: 'The product or offer has no clearly stated name visible in the hero or primary content area. A visitor cannot refer to, recall, or share what they are considering buying. Unnamed offers cannot be searched for, recommended, or remembered after the session ends.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any', passLabel: 'Offer clearly named' },
  { id: 'OFC_002', category: 'Offer Clarity', categoryNumber: 27, title: 'No "what\'s included" clarity — offer contents not enumerated', failCondition: 'The page does not specify what is included in the product or service. A visitor cannot determine exactly what they will receive for their money without reading through ancillary pages. Unspecified offer contents force the visitor to assume — and assumption defaults to skepticism.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'OFC_003', category: 'Offer Clarity', categoryNumber: 27, title: 'Offer scope is ambiguous — inclusions and exclusions not stated', failCondition: 'FAIL if BODY/SECTIONS/PRICING never state what is and is not included in the offer/package — no inclusions/exclusions or scope boundaries. PASS if the scope is enumerated (what you get, what you do not). Quote the inclusion list or confirm its absence.', mode: 'GAP', severity: 'Medium', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'OFC_004', category: 'Offer Clarity', categoryNumber: 27, title: 'No delivery or fulfillment expectation set', failCondition: 'No indication of when or how the product will be delivered after purchase — no dispatch timeline, download link expectation, access instructions, or fulfillment process described. Delivery uncertainty is a significant purchase barrier when timing matters to the buyer.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'OFC_005', category: 'Offer Clarity', categoryNumber: 27, title: 'Minimum commitment not stated for subscription or retainer offers', failCondition: 'For subscription products, service retainers, or ongoing agreements, no minimum term, cancellation window, or commitment duration is stated. Buyers who cannot determine their minimum obligation before purchasing perceive higher risk and convert at lower rates.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any' },
  { id: 'OFC_006', category: 'Offer Clarity', categoryNumber: 27, title: 'Time to value not communicated', failCondition: 'No signal indicates how quickly a new user can expect to see results or get the product working — no "live in 5 minutes", "results in 90 seconds", "setup in one afternoon", or equivalent time-to-value statement. Uncertainty about time investment is a primary objection for busy buyers evaluating whether adoption cost is justified.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any', passLabel: 'Time to value communicated' },
  { id: 'OFC_007', category: 'Offer Clarity', categoryNumber: 27, title: 'No specific verifiable claim present', failCondition: 'Page contains no specific, verifiable claim — no customer count, concrete metric, named result, or data point a skeptical buyer could independently verify or find plausible. Pages built entirely on unanchored assertions give buyers no factual hook on which to justify the purchase decision.', mode: 'GAP', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any', passLabel: 'Verifiable claim present' },
  { id: 'OFC_008', category: 'Offer Clarity', categoryNumber: 27, title: 'Offer inconsistency — headline, subheadline, and CTA misaligned', failCondition: 'FAIL if the HERO Headline, Subheadline, and CTA point at different outcomes/actions — they do not reinforce one consistent offer. PASS if all three align on the same outcome and next step. Quote all three and name the mismatch.', mode: 'FLAW', severity: 'High', requiresEvidence: false, siteType: 'universal', pageType: 'any', passLabel: 'Headline, sub, and CTA aligned' },
];

export default DIAGNOSTIC_CHECKS;
